package com.spotfinder;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

@Getter
@RequiredArgsConstructor
public enum HighlightStyle
{
	OUTLINE("Outline"),
	HULL("Clickbox / Hull"),
	TILE("Tile"),
	OUTLINE_AND_TILE("Outline + Tile");

	private final String displayName;

	@Override
	public String toString()
	{
		return displayName;
	}
}

package com.spotfinder;

import com.spotfinder.ranking.AccountMode;
import com.spotfinder.ranking.SortMode;
import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup(SpotFinderConfig.GROUP)
public interface SpotFinderConfig extends Config
{
	String GROUP = "spot-finder";
	String KEY_HIGHLIGHT_ONLY_NEAR_SPOT = "highlightOnlyNearSpot";

	@ConfigSection(
		name = "Navigation & Routing",
		description = "World map pins, hint arrows, and Shortest Path integration",
		position = 0
	)
	String navigationSection = "navigation";

	@ConfigSection(
		name = "Resource Highlighting",
		description = "Highlight matching trees, rocks, fishing spots, stalls, altars, and stations",
		position = 1
	)
	String highlightSection = "highlighting";

	@ConfigSection(
		name = "Nearest Bank Indicator",
		description = "Highlight the active spot's bank or deposit box and show tile distance",
		position = 2
	)
	String bankSection = "bank";

	@ConfigSection(
		name = "Ranking & Account",
		description = "Account-type weighting and boostable spot behavior",
		position = 3
	)
	String rankingSection = "ranking";

	@ConfigSection(
		name = "HUD & Defaults",
		description = "Info overlay and default side panel settings",
		position = 4
	)
	String hudSection = "hud";

	@ConfigItem(
		keyName = "routeWithShortestPath",
		name = "Route via Shortest Path",
		description = "Send the selected spot or bank target to the Shortest Path plugin automatically",
		section = navigationSection,
		position = 0
	)
	default boolean routeWithShortestPath()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showWorldMapPin",
		name = "Show World Map Pin",
		description = "Add a clickable pin on the World Map for the selected spot and its bank",
		section = navigationSection,
		position = 1
	)
	default boolean showWorldMapPin()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showHintArrow",
		name = "Show Hint Arrow Nearby",
		description = "Point an in-game hint arrow toward the active destination while it is loaded in the scene",
		section = navigationSection,
		position = 2
	)
	default boolean showHintArrow()
	{
		return true;
	}

	@ConfigItem(
		keyName = "highlightResources",
		name = "Highlight Matching Resources",
		description = "Highlight nodes, NPCs, stalls, altars, and stations for the selected resource",
		section = highlightSection,
		position = 0
	)
	default boolean highlightResources()
	{
		return true;
	}

	@ConfigItem(
		keyName = "highlightStyle",
		name = "Highlight Style",
		description = "How matched resource nodes are drawn in the game world",
		section = highlightSection,
		position = 1
	)
	default HighlightStyle highlightStyle()
	{
		return HighlightStyle.OUTLINE_AND_TILE;
	}

	@ConfigItem(
		keyName = KEY_HIGHLIGHT_ONLY_NEAR_SPOT,
		name = "Only Highlight Near Selected Spot",
		description = "Restrict highlighting to the selected spot's area. Disable to highlight matching nodes anywhere.",
		section = highlightSection,
		position = 2
	)
	default boolean highlightOnlyNearSpot()
	{
		return true;
	}

	@Alpha
	@ConfigItem(
		keyName = "resourceColor",
		name = "Resource Highlight Color",
		description = "Color used to highlight matching resources and stations",
		section = highlightSection,
		position = 3
	)
	default Color resourceColor()
	{
		return new Color(0, 216, 164, 220);
	}

	@ConfigItem(
		keyName = "highlightClosestNode",
		name = "Emphasize Closest Node",
		description = "Highlight the nearest available matching node with a brighter outline",
		section = highlightSection,
		position = 4
	)
	default boolean highlightClosestNode()
	{
		return true;
	}

	@Alpha
	@ConfigItem(
		keyName = "closestNodeColor",
		name = "Closest Node Color",
		description = "Highlight color for the closest available matching node",
		section = highlightSection,
		position = 5
	)
	default Color closestNodeColor()
	{
		return new Color(155, 255, 226, 245);
	}

	@Range(min = 1, max = 5)
	@ConfigItem(
		keyName = "outlineWidth",
		name = "Outline Width",
		description = "Stroke width in pixels for model and tile outlines",
		section = highlightSection,
		position = 6
	)
	default int outlineWidth()
	{
		return 2;
	}

	@Range(min = 0, max = 4)
	@ConfigItem(
		keyName = "outlineFeather",
		name = "Outline Feather",
		description = "Softness of model outlines",
		section = highlightSection,
		position = 7
	)
	default int outlineFeather()
	{
		return 1;
	}

	@ConfigItem(
		keyName = "showMinimapDots",
		name = "Show Minimap Dots & Arrow",
		description = "Show matching nodes, bank markers, and a bearing arrow on the minimap",
		section = highlightSection,
		position = 8
	)
	default boolean showMinimapDots()
	{
		return true;
	}

	@ConfigItem(
		keyName = "highlightNearestBank",
		name = "Highlight Spot Bank / Deposit Box",
		description = "Highlight the active spot's bank booth, bank chest, or deposit box in the scene",
		section = bankSection,
		position = 0
	)
	default boolean highlightNearestBank()
	{
		return true;
	}

	@Alpha
	@ConfigItem(
		keyName = "bankColor",
		name = "Bank Highlight Color",
		description = "Color used to highlight the bank or deposit box",
		section = bankSection,
		position = 1
	)
	default Color bankColor()
	{
		return new Color(245, 184, 46, 230);
	}

	@ConfigItem(
		keyName = "showBankDistanceLabel",
		name = "Show Bank Distance Label",
		description = "Display the bank or deposit box name and tile distance over the object",
		section = bankSection,
		position = 2
	)
	default boolean showBankDistanceLabel()
	{
		return true;
	}

	@ConfigItem(
		keyName = "accountMode",
		name = "Account Weighting",
		description = "Auto-detect Ironman/UIM weighting or force Main, Ironman, or UIM scoring",
		section = rankingSection,
		position = 0
	)
	default AccountMode accountMode()
	{
		return AccountMode.AUTO;
	}

	@ConfigItem(
		keyName = "showBoostableSpots",
		name = "Show Boostable Spots (+5)",
		description = "Mark spots within 5 levels of your real level as BOOSTABLE instead of LOCKED",
		section = rankingSection,
		position = 1
	)
	default boolean showBoostableSpots()
	{
		return true;
	}

	@ConfigItem(
		keyName = "includeBoostableInUnlocked",
		name = "Include Boostable in Unlocked Filter",
		description = "Keep BOOSTABLE spots visible when the Unlocked filter pill is enabled",
		section = rankingSection,
		position = 2
	)
	default boolean includeBoostableInUnlocked()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showInfoOverlay",
		name = "Show Active Spot HUD",
		description = "Show a compact top-left overlay with active spot status, node count, and bank distance",
		section = hudSection,
		position = 0
	)
	default boolean showInfoOverlay()
	{
		return true;
	}

	@ConfigItem(
		keyName = "defaultSortMode",
		name = "Default Sort Mode",
		description = "Initial ranking order before saved session state overrides it",
		section = hudSection,
		position = 1
	)
	default SortMode defaultSortMode()
	{
		return SortMode.BEST_OVERALL;
	}

	@ConfigItem(
		keyName = "hideLockedByDefault",
		name = "Hide Locked Spots by Default",
		description = "Default state for the Unlocked filter pill",
		section = hudSection,
		position = 2
	)
	default boolean hideLockedByDefault()
	{
		return false;
	}

	@ConfigItem(
		keyName = "includeWildernessByDefault",
		name = "Include Wilderness Spots by Default",
		description = "Default state for the Wildy filter pill",
		section = hudSection,
		position = 3
	)
	default boolean includeWildernessByDefault()
	{
		return false;
	}
}

package com.spotfinder;

import com.google.inject.Provides;
import com.spotfinder.data.AccountSnapshot;
import com.spotfinder.data.DiaryTier;
import com.spotfinder.data.GatheringSpot;
import com.spotfinder.data.SpotCatalog;
import com.spotfinder.overlay.SceneResourceTracker;
import com.spotfinder.overlay.SpotInfoOverlay;
import com.spotfinder.overlay.SpotMinimapOverlay;
import com.spotfinder.overlay.SpotRouteManager;
import com.spotfinder.overlay.SpotSceneOverlay;
import com.spotfinder.ranking.SortMode;
import com.spotfinder.ui.SpotFinderPanel;
import java.awt.image.BufferedImage;
import java.util.HashSet;
import java.util.Set;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameObjectDespawned;
import net.runelite.api.events.GameObjectSpawned;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.NpcDespawned;
import net.runelite.api.events.NpcSpawned;
import net.runelite.api.events.StatChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.events.WallObjectDespawned;
import net.runelite.api.events.WallObjectSpawned;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ImageUtil;

@Slf4j
@PluginDescriptor(
	name = "Spot Finder",
	description = "Account-aware spot finder for Woodcutting, Mining, Fishing, Hunter, Thieving, Agility, Runecraft, and Skilling Stations",
	tags = {"skilling", "woodcutting", "mining", "fishing", "hunter", "thieving", "agility", "runecraft", "stations", "spots", "bank", "shortestpath"}
)
public class SpotFinderPlugin extends Plugin
{
	private static final int DISTANCE_REFRESH_THRESHOLD_TILES = 8;
	private static final Set<Integer> TRACKED_VARBITS = new HashSet<>();

	static
	{
		TRACKED_VARBITS.add(VarbitID.IRONMAN);
		for (DiaryTier diary : DiaryTier.values())
		{
			TRACKED_VARBITS.add(diary.getVarbitId());
		}
	}

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private SkillIconManager skillIconManager;

	@Inject
	private ItemManager itemManager;

	@Inject
	private SpotFinderConfig config;

	@Inject
	private SpotRouteManager routeManager;

	@Inject
	private SceneResourceTracker sceneTracker;

	@Inject
	private SpotSceneOverlay sceneOverlay;

	@Inject
	private SpotMinimapOverlay minimapOverlay;

	@Inject
	private SpotInfoOverlay infoOverlay;

	private SpotFinderPanel panel;
	private NavigationButton navButton;

	private boolean accountRefreshNeeded;
	private WorldPoint lastSnapshotLocation;

	@Override
	protected void startUp()
	{
		overlayManager.add(sceneOverlay);
		overlayManager.add(minimapOverlay);
		overlayManager.add(infoOverlay);

		panel = new SpotFinderPanel(
			config,
			configManager,
			skillIconManager,
			itemManager,
			this::handleSelectSpot,
			this::clearActiveSpot,
			this::requestAccountRefresh
		);

		BufferedImage icon = ImageUtil.loadImageResource(SpotFinderPlugin.class, "/com/spotfinder/icon.png");
		navButton = NavigationButton.builder()
			.tooltip("Spot Finder")
			.icon(icon)
			.priority(6)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);

		if (client.getGameState() == GameState.LOGGED_IN)
		{
			requestAccountRefresh();
		}

		log.debug("Spot Finder started");
	}

	@Override
	protected void shutDown()
	{
		if (navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
			navButton = null;
		}
		overlayManager.remove(sceneOverlay);
		overlayManager.remove(minimapOverlay);
		overlayManager.remove(infoOverlay);

		routeManager.shutDown();
		sceneTracker.clear();
		panel = null;
		lastSnapshotLocation = null;
		accountRefreshNeeded = false;

		log.debug("Spot Finder stopped");
	}

	@Provides
	SpotFinderConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(SpotFinderConfig.class);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOADING || state == GameState.HOPPING || state == GameState.LOGIN_SCREEN)
		{
			sceneTracker.clear();
		}

		if (state == GameState.LOGIN_SCREEN)
		{
			lastSnapshotLocation = null;
			accountRefreshNeeded = false;
			if (panel != null)
			{
				panel.updateAccountState(AccountSnapshot.LOGGED_OUT);
			}
		}
		else if (state == GameState.LOGGED_IN)
		{
			accountRefreshNeeded = true;
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		accountRefreshNeeded = true;
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (TRACKED_VARBITS.contains(event.getVarbitId()))
		{
			accountRefreshNeeded = true;
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() == ChatMessageType.GAMEMESSAGE
			&& event.getMessage() != null
			&& event.getMessage().contains("completed a quest"))
		{
			accountRefreshNeeded = true;
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		routeManager.onGameTick();

		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		if (!accountRefreshNeeded && panel != null && panel.getSelectedSortMode() == SortMode.NEAREST_TO_ME)
		{
			Player local = client.getLocalPlayer();
			if (local != null)
			{
				WorldPoint current = local.getWorldLocation();
				if (lastSnapshotLocation == null
					|| lastSnapshotLocation.getPlane() != current.getPlane()
					|| lastSnapshotLocation.distanceTo2D(current) >= DISTANCE_REFRESH_THRESHOLD_TILES)
				{
					accountRefreshNeeded = true;
				}
			}
		}

		if (accountRefreshNeeded)
		{
			accountRefreshNeeded = false;
			refreshAccountSnapshotNow();
		}
	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned event)
	{
		sceneTracker.onTileObjectSpawned(event.getGameObject());
	}

	@Subscribe
	public void onGameObjectDespawned(GameObjectDespawned event)
	{
		sceneTracker.onTileObjectDespawned(event.getGameObject());
	}

	@Subscribe
	public void onWallObjectSpawned(WallObjectSpawned event)
	{
		sceneTracker.onTileObjectSpawned(event.getWallObject());
	}

	@Subscribe
	public void onWallObjectDespawned(WallObjectDespawned event)
	{
		sceneTracker.onTileObjectDespawned(event.getWallObject());
	}

	@Subscribe
	public void onNpcSpawned(NpcSpawned event)
	{
		sceneTracker.onNpcSpawned(event.getNpc());
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned event)
	{
		sceneTracker.onNpcDespawned(event.getNpc());
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!SpotFinderConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}
		routeManager.onConfigUpdated();
		if (panel != null)
		{
			panel.onConfigUpdated();
		}
	}

	private void handleSelectSpot(GatheringSpot spot, SpotRouteManager.RouteDestination destination)
	{
		routeManager.selectAndRoute(spot, destination);
		clientThread.invokeLater(() -> sceneTracker.setActiveResource(spot.getResource()));
		if (panel != null)
		{
			panel.updateActiveSpot(spot, destination, routeManager.isShortestPathAvailable());
		}
	}

	public void clearActiveSpot()
	{
		routeManager.clearRoute();
		clientThread.invokeLater(() -> sceneTracker.setActiveResource(null));
		if (panel != null)
		{
			panel.updateActiveSpot(null, SpotRouteManager.RouteDestination.SPOT, routeManager.isShortestPathAvailable());
		}
	}

	private void requestAccountRefresh()
	{
		clientThread.invokeLater(this::refreshAccountSnapshotNow);
	}

	private void refreshAccountSnapshotNow()
	{
		AccountSnapshot snapshot = AccountSnapshot.fromClient(client, SpotCatalog.getTrackedQuests());
		lastSnapshotLocation = snapshot.getPlayerLocation();
		if (panel != null)
		{
			panel.updateAccountState(snapshot);
		}
	}
}

package com.spotfinder.data;

import java.util.Collections;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.Map;
import java.util.Set;
import javax.annotation.Nullable;
import lombok.Builder;
import lombok.Value;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import net.runelite.api.WorldType;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.VarbitID;

@Value
@Builder
public class AccountSnapshot
{
	public enum IronmanType
	{
		NORMAL(""),
		IRONMAN("IM"),
		ULTIMATE_IRONMAN("UIM"),
		HARDCORE_IRONMAN("HCIM"),
		GROUP_IRONMAN("GIM"),
		HARDCORE_GROUP_IRONMAN("HCGIM");

		private final String shortLabel;

		IronmanType(String shortLabel)
		{
			this.shortLabel = shortLabel;
		}

		public String getShortLabel()
		{
			return shortLabel;
		}
	}

	public static final AccountSnapshot LOGGED_OUT = AccountSnapshot.builder()
		.loggedIn(false)
		.membersWorld(true)
		.accountType(IronmanType.NORMAL)
		.skillLevels(Collections.emptyMap())
		.completedQuests(Collections.emptySet())
		.completedDiaries(Collections.emptySet())
		.build();

	boolean loggedIn;
	boolean membersWorld;
	@Builder.Default
	IronmanType accountType = IronmanType.NORMAL;
	@Nullable
	WorldPoint playerLocation;
	Map<Skill, Integer> skillLevels;
	Set<Quest> completedQuests;
	Set<DiaryTier> completedDiaries;

	public int getSkillLevel(Skill skill)
	{
		if (!loggedIn || skillLevels == null)
		{
			return 1;
		}
		return skillLevels.getOrDefault(skill, 1);
	}

	public boolean hasCompletedQuest(Quest quest)
	{
		return loggedIn && completedQuests != null && completedQuests.contains(quest);
	}

	public boolean hasCompletedDiary(DiaryTier diary)
	{
		return loggedIn && completedDiaries != null && completedDiaries.contains(diary);
	}

	public boolean isUltimateIronman()
	{
		return accountType == IronmanType.ULTIMATE_IRONMAN;
	}

	public boolean isIronmanFamily()
	{
		return accountType != null && accountType != IronmanType.NORMAL;
	}

	public String getAccountTypeShortLabel()
	{
		return accountType != null ? accountType.getShortLabel() : "";
	}

	/**
	 * Must be called on the RuneLite client thread.
	 */
	public static AccountSnapshot fromClient(Client client, Set<Quest> trackedQuests)
	{
		if (client == null || client.getGameState() != GameState.LOGGED_IN)
		{
			return LOGGED_OUT;
		}

		Map<Skill, Integer> levels = new EnumMap<>(Skill.class);
		for (Skill skill : Skill.values())
		{
			if (!"Overall".equalsIgnoreCase(skill.getName()))
			{
				levels.put(skill, client.getRealSkillLevel(skill));
			}
		}

		Set<Quest> finishedQuests = EnumSet.noneOf(Quest.class);
		for (Quest quest : trackedQuests)
		{
			if (quest.getState(client) == QuestState.FINISHED)
			{
				finishedQuests.add(quest);
			}
		}

		Set<DiaryTier> finishedDiaries = EnumSet.noneOf(DiaryTier.class);
		for (DiaryTier diary : DiaryTier.values())
		{
			if (client.getVarbitValue(diary.getVarbitId()) >= 1)
			{
				finishedDiaries.add(diary);
			}
		}

		Player localPlayer = client.getLocalPlayer();
		WorldPoint location = localPlayer != null ? localPlayer.getWorldLocation() : null;
		boolean members = client.getWorldType().contains(WorldType.MEMBERS);
		IronmanType detectedType = decodeAccountType(client.getVarbitValue(VarbitID.IRONMAN));

		return AccountSnapshot.builder()
			.loggedIn(true)
			.membersWorld(members)
			.accountType(detectedType)
			.playerLocation(location)
			.skillLevels(Collections.unmodifiableMap(levels))
			.completedQuests(Collections.unmodifiableSet(finishedQuests))
			.completedDiaries(Collections.unmodifiableSet(finishedDiaries))
			.build();
	}

	public static IronmanType decodeAccountType(int ironmanVarbit)
	{
		switch (ironmanVarbit)
		{
			case 1:
				return IronmanType.IRONMAN;
			case 2:
				return IronmanType.ULTIMATE_IRONMAN;
			case 3:
				return IronmanType.HARDCORE_IRONMAN;
			case 4:
			case 6:
				return IronmanType.GROUP_IRONMAN;
			case 5:
				return IronmanType.HARDCORE_GROUP_IRONMAN;
			default:
				return IronmanType.NORMAL;
		}
	}
}

package com.spotfinder.data;

import javax.annotation.Nullable;
import lombok.Value;
import net.runelite.api.Skill;
import net.runelite.api.coords.WorldPoint;

@Value
public class BankInfo
{
	public static final BankInfo NONE = new BankInfo("No nearby bank", null, BankType.NONE, Integer.MAX_VALUE, null, null, 0);

	String name;
	@Nullable
	WorldPoint location;
	BankType type;
	int distanceTiles;
	@Nullable
	DiaryTier bankDiaryRequirement;
	@Nullable
	Skill bankAltSkill;
	int bankAltSkillLevel;

	public static BankInfo bank(String name, WorldPoint location, int distanceTiles)
	{
		return new BankInfo(name, location, BankType.BANK, distanceTiles, null, null, 0);
	}

	public static BankInfo bank(String name, WorldPoint location, int distanceTiles, DiaryTier diaryRequirement)
	{
		return new BankInfo(name, location, BankType.BANK, distanceTiles, diaryRequirement, null, 0);
	}

	public static BankInfo bank(
		String name,
		WorldPoint location,
		int distanceTiles,
		DiaryTier diaryRequirement,
		Skill altSkill,
		int altSkillLevel)
	{
		return new BankInfo(name, location, BankType.BANK, distanceTiles, diaryRequirement, altSkill, altSkillLevel);
	}

	public static BankInfo depositBox(String name, WorldPoint location, int distanceTiles)
	{
		return new BankInfo(name, location, BankType.DEPOSIT_BOX, distanceTiles, null, null, 0);
	}

	public boolean hasBanking()
	{
		return type != BankType.NONE && location != null;
	}

	public String getBankRequirementSummary()
	{
		if (bankDiaryRequirement == null && bankAltSkill == null)
		{
			return "";
		}
		if (bankDiaryRequirement != null && bankAltSkill != null && bankAltSkillLevel > 0)
		{
			return bankDiaryRequirement.getDisplayName() + " or " + bankAltSkillLevel + " " + bankAltSkill.getName();
		}
		if (bankDiaryRequirement != null)
		{
			return bankDiaryRequirement.getDisplayName();
		}
		return bankAltSkillLevel + " " + bankAltSkill.getName();
	}
}

