package com.spotfinder.data;

import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import net.runelite.api.Quest;

public final class SpotCatalog
{
	private static final List<GatheringSpot> ALL_SPOTS;
	private static final Map<ResourceType, List<GatheringSpot>> BY_RESOURCE;
	private static final Map<GatheringSkill, List<GatheringSpot>> BY_SKILL;
	private static final Map<String, GatheringSpot> BY_ID;
	private static final Set<Quest> TRACKED_QUESTS;

	static
	{
		List<GatheringSpot> all = new ArrayList<>();
		all.addAll(WoodcuttingSpots.all());
		all.addAll(MiningSpots.all());
		all.addAll(FishingSpots.all());
		all.addAll(HunterSpots.all());
		all.addAll(ThievingSpots.all());
		all.addAll(AgilitySpots.all());
		all.addAll(RunecraftSpots.all());
		all.addAll(StationSpots.all());

		Map<ResourceType, List<GatheringSpot>> byResource = new EnumMap<>(ResourceType.class);
		Map<GatheringSkill, List<GatheringSpot>> bySkill = new EnumMap<>(GatheringSkill.class);
		Map<String, GatheringSpot> byId = new LinkedHashMap<>();
		Set<Quest> quests = EnumSet.noneOf(Quest.class);

		for (ResourceType resource : ResourceType.values())
		{
			byResource.put(resource, new ArrayList<>());
		}
		for (GatheringSkill skill : GatheringSkill.values())
		{
			bySkill.put(skill, new ArrayList<>());
		}

		for (GatheringSpot spot : all)
		{
			if (byId.put(spot.getId(), spot) != null)
			{
				throw new IllegalStateException("Duplicate spot id in catalog: " + spot.getId());
			}
			byResource.get(spot.getResource()).add(spot);
			bySkill.get(spot.getResource().getSkill()).add(spot);
			if (spot.getRequirements() != null && spot.getRequirements().getRequiredQuests() != null)
			{
				quests.addAll(spot.getRequirements().getRequiredQuests());
			}
		}

		byResource.replaceAll((k, v) -> Collections.unmodifiableList(v));
		bySkill.replaceAll((k, v) -> Collections.unmodifiableList(v));

		ALL_SPOTS = Collections.unmodifiableList(all);
		BY_RESOURCE = Collections.unmodifiableMap(byResource);
		BY_SKILL = Collections.unmodifiableMap(bySkill);
		BY_ID = Collections.unmodifiableMap(byId);
		TRACKED_QUESTS = Collections.unmodifiableSet(quests);
	}

	private SpotCatalog()
	{
	}

	public static List<GatheringSpot> getAllSpots()
	{
		return ALL_SPOTS;
	}

	public static List<GatheringSpot> getSpotsForResource(ResourceType resource)
	{
		return BY_RESOURCE.getOrDefault(resource, Collections.emptyList());
	}

	public static List<GatheringSpot> getSpotsForSkill(GatheringSkill skill)
	{
		return BY_SKILL.getOrDefault(skill, Collections.emptyList());
	}

	public static Optional<GatheringSpot> findById(String id)
	{
		return Optional.ofNullable(BY_ID.get(id));
	}

	public static Set<Quest> getTrackedQuests()
	{
		return TRACKED_QUESTS;
	}
}

package com.spotfinder.data;

import java.util.Collections;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import lombok.Builder;
import lombok.Singular;
import lombok.Value;
import net.runelite.api.Quest;
import net.runelite.api.Skill;

@Value
@Builder
public class SpotRequirement
{
	public static final SpotRequirement F2P_OPEN = SpotRequirement.builder().membersOnly(false).build();
	public static final SpotRequirement MEMBERS_OPEN = SpotRequirement.builder().membersOnly(true).build();

	boolean membersOnly;

	@Singular("skillLevel")
	Map<Skill, Integer> extraSkillLevels;

	@Singular("quest")
	List<Quest> requiredQuests;

	@Singular("diary")
	List<DiaryTier> requiredDiaries;

	String extraNote;

	public Map<Skill, Integer> getEffectiveSkillLevels(GatheringSkill primarySkill, int baseLevel)
	{
		Map<Skill, Integer> combined = new EnumMap<>(Skill.class);
		combined.put(primarySkill.getApiSkill(), baseLevel);
		if (extraSkillLevels != null)
		{
			for (Map.Entry<Skill, Integer> entry : extraSkillLevels.entrySet())
			{
				combined.merge(entry.getKey(), entry.getValue(), Math::max);
			}
		}
		return Collections.unmodifiableMap(combined);
	}
}

package com.spotfinder.overlay;

import com.spotfinder.data.BankInfo;
import com.spotfinder.data.GatheringSpot;
import com.spotfinder.data.ResourceType;
import java.util.Collections;
import java.util.HashSet;
import java.util.Set;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.GameState;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.ObjectComposition;
import net.runelite.api.Scene;
import net.runelite.api.Tile;
import net.runelite.api.TileObject;
import net.runelite.api.WallObject;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;

/**
 * Event-driven scene tracker for active resource objects, resource NPCs, and loaded bank/deposit objects.
 * Avoids per-frame or per-tick full-scene scans; scans once only when the active resource changes.
 */
@Singleton
public class SceneResourceTracker
{
	private static final int BANK_SEARCH_RADIUS_AROUND_HINT = 12;
	private static final int BANK_FALLBACK_MAX_DISTANCE = 48;

	private final Client client;
	private final Set<TileObject> trackedResources = new HashSet<>();
	private final Set<NPC> trackedNpcs = new HashSet<>();
	private final Set<TileObject> trackedBanks = new HashSet<>();
	private final Set<TileObject> trackedResourcesView = Collections.unmodifiableSet(trackedResources);
	private final Set<NPC> trackedNpcsView = Collections.unmodifiableSet(trackedNpcs);
	private final Set<TileObject> trackedBanksView = Collections.unmodifiableSet(trackedBanks);

	@Nullable
	private ResourceType activeResource;

	@Inject
	public SceneResourceTracker(Client client)
	{
		this.client = client;
	}

	public Set<TileObject> getTrackedResources()
	{
		return trackedResourcesView;
	}

	public Set<NPC> getTrackedNpcs()
	{
		return trackedNpcsView;
	}

	public Set<TileObject> getTrackedBanks()
	{
		return trackedBanksView;
	}

	public void clear()
	{
		trackedResources.clear();
		trackedNpcs.clear();
		trackedBanks.clear();
	}

	/**
	 * Updates the tracked resource type and performs a one-time scan of the currently loaded scene
	 * so already-visible nodes highlight immediately. Must be invoked on the client thread.
	 */
	public void setActiveResource(@Nullable ResourceType resource)
	{
		this.activeResource = resource;
		trackedResources.clear();
		trackedNpcs.clear();

		if (client.getGameState() != GameState.LOGGED_IN)
		{
			trackedBanks.clear();
			return;
		}

		WorldView worldView = client.getTopLevelWorldView();
		if (worldView == null)
		{
			return;
		}

		boolean needBankScan = trackedBanks.isEmpty();
		Scene scene = worldView.getScene();
		if (scene != null && (resource != null || needBankScan))
		{
			Tile[][][] tiles = scene.getTiles();
			if (tiles != null)
			{
				// Scan all loaded planes so climbing ladders/stairs (e.g. Redwood platforms) needs no rescan.
				for (Tile[][] planeTiles : tiles)
				{
					if (planeTiles == null)
					{
						continue;
					}
					for (Tile[] column : planeTiles)
					{
						if (column == null)
						{
							continue;
						}
						for (Tile tile : column)
						{
							if (tile == null)
							{
								continue;
							}
							GameObject[] gameObjects = tile.getGameObjects();
							if (gameObjects != null)
							{
								for (GameObject obj : gameObjects)
								{
									if (obj != null)
									{
										considerTileObject(obj, needBankScan);
									}
								}
							}
							WallObject wall = tile.getWallObject();
							if (wall != null)
							{
								considerTileObject(wall, needBankScan);
							}
						}
					}
				}
			}
		}

		if (resource != null && (!resource.getNpcIds().isEmpty() || resource.getNpcAction() != null))
		{
			for (NPC npc : worldView.npcs())
			{
				if (npc != null && matchesActiveNpc(npc))
				{
					trackedNpcs.add(npc);
				}
			}
		}
	}

	public void onTileObjectSpawned(TileObject obj)
	{
		if (obj == null)
		{
			return;
		}
		considerTileObject(obj, true);
	}

	public void onTileObjectDespawned(TileObject obj)
	{
		if (obj == null)
		{
			return;
		}
		trackedResources.remove(obj);
		trackedBanks.remove(obj);
	}

	public void onNpcSpawned(NPC npc)
	{
		if (npc != null && matchesActiveNpc(npc))
		{
			trackedNpcs.add(npc);
		}
	}

	public void onNpcDespawned(NPC npc)
	{
		if (npc != null)
		{
			trackedNpcs.remove(npc);
		}
	}

	/**
	 * Counts how many tracked resource nodes currently satisfy the active spot's plane and radius constraints.
	 */
	public int countVisibleMatchingNodes(@Nullable GatheringSpot spot, boolean onlyNearSpot)
	{
		if (spot == null)
		{
			return 0;
		}
		WorldView worldView = client.getTopLevelWorldView();
		int plane = worldView != null ? worldView.getPlane() : 0;
		int count = 0;

		for (TileObject obj : trackedResources)
		{
			if (isNodeInScope(obj.getWorldLocation(), plane, spot, onlyNearSpot))
			{
				count++;
			}
		}
		for (NPC npc : trackedNpcs)
		{
			if (isNodeInScope(npc.getWorldLocation(), plane, spot, onlyNearSpot))
			{
				count++;
			}
		}
		return count;
	}

	public static boolean isNodeInScope(WorldPoint nodeLoc, int currentPlane, GatheringSpot spot, boolean onlyNearSpot)
	{
		if (nodeLoc == null || nodeLoc.getPlane() != currentPlane)
		{
			return false;
		}
		ResourceType resource = spot.getResource();
		// Action-only resources (e.g. Agility "Climb") always stay scoped to the spot radius to avoid false matches.
		boolean forceLocal = resource.getObjectIds().isEmpty() && resource.getNpcIds().isEmpty();
		if (!onlyNearSpot && !forceLocal)
		{
			return true;
		}
		// Match 2D footprint on the player's active plane so multi-floor spots (e.g. Redwood platforms) stay in scope.
		return nodeLoc.distanceTo2D(spot.getLocation()) <= spot.getHighlightRadius();
	}

	/**
	 * Finds a loaded bank or deposit box object belonging to the active spot.
	 * When the spot defines a bank location, only objects near that bank are returned so unrelated
	 * banks in other towns are never mislabeled. When a spot has no predefined bank, falls back to
	 * a nearby bank only while the player is actually near the spot.
	 */
	@Nullable
	public TileObject findSpotBankObject(@Nullable GatheringSpot spot, WorldPoint playerLoc)
	{
		if (trackedBanks.isEmpty() || spot == null || playerLoc == null)
		{
			return null;
		}

		int plane = playerLoc.getPlane();
		BankInfo bankInfo = spot.getBank();
		if (bankInfo != null && bankInfo.hasBanking() && bankInfo.getLocation() != null)
		{
			WorldPoint bankHint = bankInfo.getLocation();
			if (bankHint.getPlane() != plane)
			{
				return null;
			}
			TileObject bestNearHint = null;
			int bestPlayerDist = Integer.MAX_VALUE;
			for (TileObject bankObj : trackedBanks)
			{
				WorldPoint objLoc = bankObj.getWorldLocation();
				if (objLoc == null || objLoc.getPlane() != plane)
				{
					continue;
				}
				if (objLoc.distanceTo2D(bankHint) <= BANK_SEARCH_RADIUS_AROUND_HINT)
				{
					int distToPlayer = playerLoc.distanceTo2D(objLoc);
					if (distToPlayer < bestPlayerDist)
					{
						bestPlayerDist = distToPlayer;
						bestNearHint = bankObj;
					}
				}
			}
			return bestNearHint;
		}

		boolean sameBand = (playerLoc.getY() >= 4500) == (spot.getLocation().getY() >= 4500);
		if (!sameBand || playerLoc.distanceTo2D(spot.getLocation()) > spot.getHighlightRadius() + 24)
		{
			return null;
		}

		TileObject bestNearPlayer = null;
		int bestPlayerDist = BANK_FALLBACK_MAX_DISTANCE;
		for (TileObject bankObj : trackedBanks)
		{
			WorldPoint objLoc = bankObj.getWorldLocation();
			if (objLoc == null || objLoc.getPlane() != plane)
			{
				continue;
			}
			int distToPlayer = playerLoc.distanceTo2D(objLoc);
			if (distToPlayer < bestPlayerDist)
			{
				bestPlayerDist = distToPlayer;
				bestNearPlayer = bankObj;
			}
		}
		return bestNearPlayer;
	}

	private void considerTileObject(TileObject obj, boolean checkBank)
	{
		ResourceType resource = activeResource;
		boolean matchedResource = false;
		if (resource != null && resource.matchesObjectId(obj.getId()))
		{
			trackedResources.add(obj);
			matchedResource = true;
		}

		boolean needActionResource = resource != null && !matchedResource && resource.getObjectAction() != null;
		if (!checkBank && !needActionResource)
		{
			return;
		}

		String[] actions = getResolvedObjectActions(obj.getId());
		if (actions == null)
		{
			return;
		}
		for (String action : actions)
		{
			if (action == null)
			{
				continue;
			}
			if (needActionResource && action.equalsIgnoreCase(resource.getObjectAction()))
			{
				trackedResources.add(obj);
			}
			if (checkBank && (action.equalsIgnoreCase("Bank") || action.equalsIgnoreCase("Deposit")))
			{
				trackedBanks.add(obj);
			}
		}
	}

	private boolean matchesActiveNpc(NPC npc)
	{
		ResourceType resource = activeResource;
		if (resource == null)
		{
			return false;
		}
		if (resource.matchesNpcId(npc.getId()))
		{
			return true;
		}
		String expectedAction = resource.getNpcAction();
		if (expectedAction == null)
		{
			return false;
		}
		NPCComposition comp = npc.getTransformedComposition();
		if (comp == null)
		{
			comp = npc.getComposition();
		}
		if (comp == null || comp.getActions() == null)
		{
			return false;
		}
		for (String action : comp.getActions())
		{
			if (action != null && action.equalsIgnoreCase(expectedAction))
			{
				return true;
			}
		}
		return false;
	}

	@Nullable
	private String[] getResolvedObjectActions(int objectId)
	{
		ObjectComposition comp = client.getObjectDefinition(objectId);
		if (comp == null)
		{
			return null;
		}
		if (comp.getImpostorIds() != null)
		{
			comp = comp.getImpostor();
			if (comp == null)
			{
				return null;
			}
		}
		return comp.getActions();
	}
}

package com.spotfinder.overlay;

import com.spotfinder.SpotFinderConfig;
import com.spotfinder.SpotFinderPlugin;
import com.spotfinder.data.BankInfo;
import com.spotfinder.data.GatheringSpot;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.Player;
import net.runelite.api.TileObject;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

public class SpotInfoOverlay extends OverlayPanel
{
	private static final Color GUILD_BOOST_COLOR = new Color(120, 215, 255);
	private static final Color WARN_AMBER = new Color(245, 192, 72);
	private static final int MIN_PANEL_WIDTH = 185;
	private static final int MAX_PANEL_WIDTH = 280;
	private static final int COLUMN_GAP = 14;
	private static final int HORIZONTAL_PADDING = 22;

	private final Client client;
	private final SpotFinderConfig config;
	private final SpotRouteManager routeManager;
	private final SceneResourceTracker tracker;

	@Inject
	public SpotInfoOverlay(
		Client client,
		SpotFinderPlugin plugin,
		SpotFinderConfig config,
		SpotRouteManager routeManager,
		SceneResourceTracker tracker)
	{
		super(plugin);
		this.client = client;
		this.config = config;
		this.routeManager = routeManager;
		this.tracker = tracker;

		setPosition(OverlayPosition.TOP_LEFT);
		addMenuEntry(MenuAction.RUNELITE_OVERLAY, "Deselect", "Spot Finder", e -> plugin.clearActiveSpot());
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showInfoOverlay())
		{
			return null;
		}
		GatheringSpot spot = routeManager.getActiveSpot();
		if (spot == null)
		{
			return null;
		}

		Player localPlayer = client.getLocalPlayer();
		WorldPoint playerLoc = localPlayer != null ? localPlayer.getWorldLocation() : null;
		FontMetrics fm = graphics.getFontMetrics();
		boolean routingToBank = routeManager.getRouteDestination() == SpotRouteManager.RouteDestination.BANK
			&& spot.getBank().hasBanking();

		String title = spot.getResource().getDisplayName();
		int widest = fm.stringWidth(title);

		panelComponent.getChildren().add(TitleComponent.builder()
			.text(title)
			.color(routingToBank ? config.bankColor() : config.resourceColor())
			.build());

		widest = addRow(fm, widest, "Spot:", spot.getName(), Color.WHITE);

		if (routingToBank)
		{
			widest = addRow(fm, widest, "Target:", spot.getBank().getName(), config.bankColor());
		}

		String distanceText = routingToBank
			? formatPointDistance(spot.getBank().getLocation(), 2, playerLoc, "At bank")
			: formatPointDistance(spot.getLocation(), spot.getHighlightRadius(), playerLoc, "At spot");
		Color distanceColor = ("At spot".equals(distanceText) || "At bank".equals(distanceText))
			? ColorScheme.PROGRESS_COMPLETE_COLOR
			: Color.LIGHT_GRAY;
		widest = addRow(fm, widest, "Distance:", distanceText, distanceColor);

		int visibleNodes = tracker.countVisibleMatchingNodes(spot, config.highlightOnlyNearSpot());
		widest = addRow(
			fm,
			widest,
			"Loaded:",
			visibleNodes + " / " + spot.getNodeCount() + " nodes",
			visibleNodes > 0 ? config.resourceColor() : Color.LIGHT_GRAY
		);

		widest = addBankRow(fm, widest, spot, playerLoc);

		if (config.routeWithShortestPath())
		{
			boolean spReady = routeManager.isShortestPathAvailable();
			widest = addRow(
				fm,
				widest,
				"Route:",
				spReady ? "Shortest Path" : "Map pin (no Shortest Path)",
				spReady ? ColorScheme.PROGRESS_COMPLETE_COLOR : WARN_AMBER
			);
		}

		if (spot.isGuildBoost())
		{
			widest = addRow(fm, widest, "Bonus:", "+7 guild boost", GUILD_BOOST_COLOR);
		}

		if (spot.isWilderness())
		{
			widest = addRow(fm, widest, "Warning:", "Wilderness PvP", ColorScheme.PROGRESS_ERROR_COLOR);
		}

		int panelWidth = Math.min(MAX_PANEL_WIDTH, Math.max(MIN_PANEL_WIDTH, widest + HORIZONTAL_PADDING));
		panelComponent.setPreferredSize(new Dimension(panelWidth, 0));

		return super.render(graphics);
	}

	private int addRow(FontMetrics fm, int currentMax, String left, String right, Color rightColor)
	{
		panelComponent.getChildren().add(LineComponent.builder()
			.left(left)
			.right(right)
			.rightColor(rightColor)
			.build());

		int rowWidth = fm.stringWidth(left) + COLUMN_GAP + fm.stringWidth(right);
		return Math.max(currentMax, rowWidth);
	}

	private int addBankRow(FontMetrics fm, int currentMax, GatheringSpot spot, WorldPoint playerLoc)
	{
		BankInfo bankInfo = spot.getBank();
		TileObject spotBank = playerLoc != null ? tracker.findSpotBankObject(spot, playerLoc) : null;

		if (spotBank != null)
		{
			int liveDist = playerLoc.distanceTo2D(spotBank.getWorldLocation());
			String bankLabel = (bankInfo != null && bankInfo.hasBanking())
				? liveDist + "t (" + bankInfo.getName() + ")"
				: liveDist + "t (Nearby Bank)";
			return addRow(fm, currentMax, "Bank:", bankLabel, config.bankColor());
		}

		if (bankInfo != null && bankInfo.hasBanking())
		{
			String bankLabel = bankInfo.getDistanceTiles() + "t (" + bankInfo.getName() + ")";
			return addRow(fm, currentMax, "Spot bank:", bankLabel, config.bankColor());
		}

		return addRow(fm, currentMax, "Spot bank:", "None nearby", Color.GRAY);
	}

	private static String formatPointDistance(WorldPoint target, int arrivalRadius, WorldPoint playerLoc, String arrivedLabel)
	{
		if (playerLoc == null || target == null)
		{
			return "Unknown";
		}
		if (playerLoc.getPlane() != target.getPlane())
		{
			return "Floor " + target.getPlane();
		}
		boolean playerUnderground = playerLoc.getY() >= 4500;
		boolean spotUnderground = target.getY() >= 4500;
		if (playerUnderground != spotUnderground)
		{
			return spotUnderground ? "Underground" : "Surface";
		}
		int dist = playerLoc.distanceTo2D(target);
		if (dist <= arrivalRadius)
		{
			return arrivedLabel;
		}
		return dist + " tiles";
	}
}

package com.spotfinder.overlay;

import com.spotfinder.SpotFinderConfig;
import com.spotfinder.data.BankInfo;
import com.spotfinder.data.GatheringSpot;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.TileObject;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

public class SpotMinimapOverlay extends Overlay
{
	private static final int MINIMAP_BEARING_TILES = 14;
	private static final int MINIMAP_BEARING_MIN_DIST = 16;

	private final Client client;
	private final SpotFinderConfig config;
	private final SpotRouteManager routeManager;
	private final SceneResourceTracker tracker;

	private final Polygon arrowPoly = new Polygon(new int[3], new int[3], 3);

	@Inject
	public SpotMinimapOverlay(
		Client client,
		SpotFinderConfig config,
		SpotRouteManager routeManager,
		SceneResourceTracker tracker)
	{
		this.client = client;
		this.config = config;
		this.routeManager = routeManager;
		this.tracker = tracker;

		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showMinimapDots())
		{
			return null;
		}
		GatheringSpot activeSpot = routeManager.getActiveSpot();
		if (activeSpot == null)
		{
			return null;
		}

		Player localPlayer = client.getLocalPlayer();
		WorldView worldView = client.getTopLevelWorldView();
		if (localPlayer == null || worldView == null)
		{
			return null;
		}

		WorldPoint playerLoc = localPlayer.getWorldLocation();
		int plane = worldView.getPlane();
		boolean onlyNearSpot = config.highlightOnlyNearSpot();
		Color resourceColor = config.resourceColor();

		if (config.highlightResources())
		{
			for (TileObject obj : tracker.getTrackedResources())
			{
				if (!SceneResourceTracker.isNodeInScope(obj.getWorldLocation(), plane, activeSpot, onlyNearSpot))
				{
					continue;
				}
				drawDot(graphics, obj.getLocalLocation(), resourceColor);
			}

			for (NPC npc : tracker.getTrackedNpcs())
			{
				if (!SceneResourceTracker.isNodeInScope(npc.getWorldLocation(), plane, activeSpot, onlyNearSpot))
				{
					continue;
				}
				drawDot(graphics, npc.getLocalLocation(), resourceColor);
			}
		}

		if (config.highlightNearestBank())
		{
			LocalPoint bankLocal = resolveBankLocalPoint(activeSpot, playerLoc, worldView);
			if (bankLocal != null)
			{
				Point minimapPt = Perspective.localToMinimap(client, bankLocal);
				if (minimapPt != null)
				{
					drawBankMarker(graphics, minimapPt, config.bankColor());
				}
			}
		}

		renderTargetBearingArrow(graphics, localPlayer, playerLoc, worldView);
		return null;
	}

	private void renderTargetBearingArrow(Graphics2D graphics, Player localPlayer, WorldPoint playerLoc, WorldView worldView)
	{
		WorldPoint target = routeManager.getActiveTargetPoint();
		if (target == null)
		{
			return;
		}

		boolean sameBand = (playerLoc.getY() >= 4500) == (target.getY() >= 4500);
		if (!sameBand)
		{
			return;
		}

		int dist = playerLoc.distanceTo2D(target);
		if (dist <= MINIMAP_BEARING_MIN_DIST)
		{
			return;
		}

		LocalPoint playerLocal = localPlayer.getLocalLocation();
		Point centerPt = Perspective.localToMinimap(client, playerLocal);
		if (centerPt == null)
		{
			return;
		}

		double dx = target.getX() - playerLoc.getX();
		double dy = target.getY() - playerLoc.getY();
		double len = Math.hypot(dx, dy);
		if (len <= 0.0)
		{
			return;
		}

		int stepX = (int) Math.round((dx / len) * MINIMAP_BEARING_TILES * Perspective.LOCAL_TILE_SIZE);
		int stepY = (int) Math.round((dy / len) * MINIMAP_BEARING_TILES * Perspective.LOCAL_TILE_SIZE);
		LocalPoint projected = new LocalPoint(playerLocal.getX() + stepX, playerLocal.getY() + stepY, worldView);
		Point edgePt = Perspective.localToMinimap(client, projected);
		if (edgePt == null)
		{
			return;
		}

		double angle = Math.atan2(edgePt.getY() - centerPt.getY(), edgePt.getX() - centerPt.getX());
		Color arrowColor = routeManager.getRouteDestination() == SpotRouteManager.RouteDestination.BANK
			? config.bankColor()
			: config.resourceColor();

		drawDirectionArrow(graphics, edgePt.getX(), edgePt.getY(), angle, arrowColor);
	}

	private void drawDirectionArrow(Graphics2D graphics, int cx, int cy, double angle, Color fill)
	{
		double tipX = cx + Math.cos(angle) * 6.5;
		double tipY = cy + Math.sin(angle) * 6.5;
		double leftX = cx + Math.cos(angle + 2.45) * 5.5;
		double leftY = cy + Math.sin(angle + 2.45) * 5.5;
		double rightX = cx + Math.cos(angle - 2.45) * 5.5;
		double rightY = cy + Math.sin(angle - 2.45) * 5.5;

		arrowPoly.xpoints[0] = (int) Math.round(tipX);
		arrowPoly.ypoints[0] = (int) Math.round(tipY);
		arrowPoly.xpoints[1] = (int) Math.round(leftX);
		arrowPoly.ypoints[1] = (int) Math.round(leftY);
		arrowPoly.xpoints[2] = (int) Math.round(rightX);
		arrowPoly.ypoints[2] = (int) Math.round(rightY);
		arrowPoly.invalidate();

		graphics.setColor(fill);
		graphics.fillPolygon(arrowPoly);
		graphics.setColor(Color.BLACK);
		graphics.drawPolygon(arrowPoly);
	}

	private void drawDot(Graphics2D graphics, LocalPoint localPoint, Color color)
	{
		if (localPoint == null)
		{
			return;
		}
		Point minimapPoint = Perspective.localToMinimap(client, localPoint);
		if (minimapPoint != null)
		{
			OverlayUtil.renderMinimapLocation(graphics, minimapPoint, color);
		}
	}

	private void drawBankMarker(Graphics2D graphics, Point pt, Color color)
	{
		int x = pt.getX();
		int y = pt.getY();
		graphics.setColor(Color.BLACK);
		graphics.fillRect(x - 3, y - 3, 7, 7);
		graphics.setColor(color);
		graphics.fillRect(x - 2, y - 2, 5, 5);
	}

	private LocalPoint resolveBankLocalPoint(GatheringSpot spot, WorldPoint playerLoc, WorldView worldView)
	{
		TileObject bankObj = tracker.findSpotBankObject(spot, playerLoc);
		if (bankObj != null)
		{
			return bankObj.getLocalLocation();
		}
		BankInfo bankInfo = spot.getBank();
		if (bankInfo != null && bankInfo.hasBanking() && bankInfo.getLocation() != null
			&& bankInfo.getLocation().getPlane() == worldView.getPlane())
		{
			LocalPoint local = LocalPoint.fromWorld(worldView, bankInfo.getLocation());
			if (local != null && worldView.contains(local))
			{
				return local;
			}
		}
		return null;
	}
}

package com.spotfinder.overlay;

import com.spotfinder.SpotFinderConfig;
import com.spotfinder.data.BankInfo;
import com.spotfinder.data.GatheringSpot;
import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.Map;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.events.PluginMessage;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.ui.overlay.worldmap.WorldMapPoint;
import net.runelite.client.ui.overlay.worldmap.WorldMapPointManager;
import net.runelite.client.util.ImageUtil;

@Slf4j
@Singleton
public class SpotRouteManager
{
	private static final String SHORTEST_PATH_NAMESPACE = "shortestpath";
	private static final int SPOT_ARRIVAL_CLEAR_TILES = 6;
	private static final int BANK_ARRIVAL_CLEAR_TILES = 2;

	public enum RouteDestination
	{
		SPOT,
		BANK
	}

	private final Client client;
	private final ClientThread clientThread;
	private final EventBus eventBus;
	private final PluginManager pluginManager;
	private final WorldMapPointManager worldMapPointManager;
	private final SpotFinderConfig config;

	private final BufferedImage spotPinImage;
	private final BufferedImage bankPinImage;

	@Getter
	@Nullable
	private volatile GatheringSpot activeSpot;

	@Getter
	private volatile RouteDestination routeDestination = RouteDestination.SPOT;

	private WorldMapPoint spotMapPoint;
	private WorldMapPoint bankMapPoint;
	private boolean shortestPathActive;
	private boolean ownsHintArrow;

	@Inject
	public SpotRouteManager(
		Client client,
		ClientThread clientThread,
		EventBus eventBus,
		PluginManager pluginManager,
		WorldMapPointManager worldMapPointManager,
		SpotFinderConfig config)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.eventBus = eventBus;
		this.pluginManager = pluginManager;
		this.worldMapPointManager = worldMapPointManager;
		this.config = config;
		this.spotPinImage = ImageUtil.loadImageResource(SpotRouteManager.class, "/com/spotfinder/map_pin.png");
		this.bankPinImage = ImageUtil.loadImageResource(SpotRouteManager.class, "/com/spotfinder/bank_pin.png");
	}

	public boolean isShortestPathAvailable()
	{
		if (pluginManager == null)
		{
			return false;
		}
		for (Plugin plugin : pluginManager.getPlugins())
		{
			if ("Shortest Path".equalsIgnoreCase(plugin.getName()) && pluginManager.isPluginEnabled(plugin))
			{
				return true;
			}
		}
		return false;
	}

	@Nullable
	public WorldPoint getActiveTargetPoint()
	{
		GatheringSpot spot = activeSpot;
		if (spot == null)
		{
			return null;
		}
		if (routeDestination == RouteDestination.BANK && spot.getBank().hasBanking())
		{
			return spot.getBank().getLocation();
		}
		return spot.getLocation();
	}

	public void selectAndRoute(GatheringSpot spot, RouteDestination destination)
	{
		if (spot == null)
		{
			clearRoute();
			return;
		}
		if (destination == RouteDestination.BANK && !spot.getBank().hasBanking())
		{
			destination = RouteDestination.SPOT;
		}

		this.activeSpot = spot;
		this.routeDestination = destination;

		refreshMapPins();

		WorldPoint target = getActiveTargetPoint();
		if (target != null)
		{
			if (config.routeWithShortestPath())
			{
				dispatchShortestPath(target);
			}
			updateHintArrowOnClientThread();
		}
	}

	public void clearRoute()
	{
		this.activeSpot = null;
		this.routeDestination = RouteDestination.SPOT;
		clearMapPins();
		clearShortestPath();
		clearOwnedHintArrow();
	}

	public void onConfigUpdated()
	{
		if (activeSpot == null)
		{
			return;
		}
		refreshMapPins();
		if (!config.showHintArrow())
		{
			clearOwnedHintArrow();
		}
		else
		{
			updateHintArrowOnClientThread();
		}
	}

	/**
	 * Called on game tick on the client thread to manage the in-scene hint arrow cleanly.
	 */
	public void onGameTick()
	{
		if (activeSpot == null || !config.showHintArrow() || client.getGameState() != GameState.LOGGED_IN)
		{
			if (ownsHintArrow)
			{
				clearHintArrowNow();
			}
			return;
		}

		WorldPoint target = getActiveTargetPoint();
		Player player = client.getLocalPlayer();
		if (target == null || player == null)
		{
			return;
		}

		WorldPoint playerLoc = player.getWorldLocation();
		if (playerLoc.getPlane() != target.getPlane())
		{
			if (ownsHintArrow)
			{
				clearHintArrowNow();
			}
			return;
		}

		int clearThreshold = routeDestination == RouteDestination.BANK
			? BANK_ARRIVAL_CLEAR_TILES
			: SPOT_ARRIVAL_CLEAR_TILES;
		int distance = playerLoc.distanceTo2D(target);
		if (distance <= clearThreshold)
		{
			if (ownsHintArrow)
			{
				clearHintArrowNow();
			}
			return;
		}

		WorldView worldView = client.getTopLevelWorldView();
		LocalPoint local = worldView != null ? LocalPoint.fromWorld(worldView, target) : null;
		if (local != null && worldView.contains(local))
		{
			if (!ownsHintArrow || !target.equals(client.getHintArrowPoint()))
			{
				// Never stomp a hint arrow belonging to a quest, slayer, or clue plugin
				if (!client.hasHintArrow() || ownsHintArrow)
				{
					client.setHintArrow(target);
					ownsHintArrow = true;
				}
			}
		}
		else if (ownsHintArrow)
		{
			clearHintArrowNow();
		}
	}

	public void shutDown()
	{
		clearRoute();
	}

	private void refreshMapPins()
	{
		clearMapPins();
		GatheringSpot spot = activeSpot;
		if (spot == null || !config.showWorldMapPin())
		{
			return;
		}

		spotMapPoint = WorldMapPoint.builder()
			.worldPoint(spot.getLocation())
			.image(spotPinImage)
			.tooltip("Spot Finder: " + spot.getResource().getDisplayName() + " - " + spot.getName())
			.name(spot.getName())
			.jumpOnClick(true)
			.snapToEdge(true)
			.build();
		worldMapPointManager.add(spotMapPoint);

		BankInfo bank = spot.getBank();
		if (bank != null && bank.hasBanking() && bank.getLocation() != null)
		{
			bankMapPoint = WorldMapPoint.builder()
				.worldPoint(bank.getLocation())
				.image(bankPinImage)
				.tooltip("Spot Finder Bank: " + bank.getName() + " (" + bank.getDistanceTiles() + "t)")
				.name(bank.getName())
				.jumpOnClick(true)
				.snapToEdge(true)
				.build();
			worldMapPointManager.add(bankMapPoint);
		}
	}

	private void clearMapPins()
	{
		if (spotMapPoint != null)
		{
			worldMapPointManager.remove(spotMapPoint);
			spotMapPoint = null;
		}
		if (bankMapPoint != null)
		{
			worldMapPointManager.remove(bankMapPoint);
			bankMapPoint = null;
		}
	}

	private void dispatchShortestPath(WorldPoint target)
	{
		clientThread.invokeLater(() -> {
			Map<String, Object> data = new HashMap<>();
			data.put("target", target);
			Player player = client.getLocalPlayer();
			if (player != null)
			{
				data.put("start", player.getWorldLocation());
			}
			eventBus.post(new PluginMessage(SHORTEST_PATH_NAMESPACE, "clear"));
			eventBus.post(new PluginMessage(SHORTEST_PATH_NAMESPACE, "path", data));
			shortestPathActive = true;
			log.debug("Posted Shortest Path route to {}", target);
		});
	}

	private void clearShortestPath()
	{
		if (!shortestPathActive)
		{
			return;
		}
		shortestPathActive = false;
		clientThread.invokeLater(() -> eventBus.post(new PluginMessage(SHORTEST_PATH_NAMESPACE, "clear")));
	}

	private void updateHintArrowOnClientThread()
	{
		clientThread.invokeLater(this::onGameTick);
	}

	private void clearOwnedHintArrow()
	{
		if (!ownsHintArrow)
		{
			return;
		}
		clientThread.invokeLater(this::clearHintArrowNow);
	}

	private void clearHintArrowNow()
	{
		if (ownsHintArrow)
		{
			client.clearHintArrow();
			ownsHintArrow = false;
		}
	}
}

package com.spotfinder.overlay;

import com.spotfinder.HighlightStyle;
import com.spotfinder.SpotFinderConfig;
import com.spotfinder.data.BankInfo;
import com.spotfinder.data.GatheringSpot;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.Shape;
import java.awt.Stroke;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.TileObject;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;

public class SpotSceneOverlay extends Overlay
{
	private static final int FILL_ALPHA = 34;
	private static final int DEST_FILL_ALPHA = 48;

	private final Client client;
	private final SpotFinderConfig config;
	private final SpotRouteManager routeManager;
	private final SceneResourceTracker tracker;
	private final ModelOutlineRenderer modelOutlineRenderer;

	private int cachedStrokeWidth = -1;
	private Stroke cachedStroke = new BasicStroke(2f);
	private Stroke cachedClosestStroke = new BasicStroke(3f);
	private Color cachedResourceColor;
	private Color cachedResourceFill;
	private Color cachedDestFill;
	private Color cachedClosestColor;
	private Color cachedClosestFill;
	private Color cachedBankColor;
	private Color cachedBankFill;

	@Inject
	public SpotSceneOverlay(
		Client client,
		SpotFinderConfig config,
		SpotRouteManager routeManager,
		SceneResourceTracker tracker,
		ModelOutlineRenderer modelOutlineRenderer)
	{
		this.client = client;
		this.config = config;
		this.routeManager = routeManager;
		this.tracker = tracker;
		this.modelOutlineRenderer = modelOutlineRenderer;

		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		GatheringSpot activeSpot = routeManager.getActiveSpot();
		if (activeSpot == null)
		{
			return null;
		}

		Player localPlayer = client.getLocalPlayer();
		WorldView worldView = client.getTopLevelWorldView();
		if (localPlayer == null || worldView == null)
		{
			return null;
		}

		WorldPoint playerLoc = localPlayer.getWorldLocation();
		int plane = worldView.getPlane();
		int outlineWidth = config.outlineWidth();
		Stroke stroke = getStroke(outlineWidth);

		if (config.highlightResources())
		{
			renderResourceNodes(graphics, activeSpot, playerLoc, plane, stroke, outlineWidth);
		}

		if (config.highlightNearestBank())
		{
			renderNearestBank(graphics, activeSpot, playerLoc, worldView, stroke);
		}

		renderDestinationMarker(graphics, activeSpot, playerLoc, worldView, stroke);
		return null;
	}

	private void renderResourceNodes(
		Graphics2D graphics,
		GatheringSpot spot,
		WorldPoint playerLoc,
		int plane,
		Stroke stroke,
		int outlineWidth)
	{
		HighlightStyle style = config.highlightStyle();
		Color borderColor = config.resourceColor();
		Color fillColor = getResourceFill(borderColor);
		boolean onlyNearSpot = config.highlightOnlyNearSpot();
		int feather = config.outlineFeather();
		boolean emphasizeClosest = config.highlightClosestNode();

		TileObject closestObj = null;
		NPC closestNpc = null;
		int closestDist = Integer.MAX_VALUE;

		if (emphasizeClosest)
		{
			for (TileObject obj : tracker.getTrackedResources())
			{
				WorldPoint loc = obj.getWorldLocation();
				if (!SceneResourceTracker.isNodeInScope(loc, plane, spot, onlyNearSpot))
				{
					continue;
				}
				int d = playerLoc.distanceTo2D(loc);
				if (d < closestDist)
				{
					closestDist = d;
					closestObj = obj;
					closestNpc = null;
				}
			}
			for (NPC npc : tracker.getTrackedNpcs())
			{
				WorldPoint loc = npc.getWorldLocation();
				if (!SceneResourceTracker.isNodeInScope(loc, plane, spot, onlyNearSpot))
				{
					continue;
				}
				int d = playerLoc.distanceTo2D(loc);
				if (d < closestDist)
				{
					closestDist = d;
					closestObj = null;
					closestNpc = npc;
				}
			}
		}

		Color closestBorder = emphasizeClosest ? config.closestNodeColor() : borderColor;
		Color closestFill = emphasizeClosest ? getClosestFill(closestBorder) : fillColor;
		int closestOutlineWidth = Math.min(5, outlineWidth + 1);
		Stroke closestStroke = getClosestStroke(outlineWidth);

		for (TileObject obj : tracker.getTrackedResources())
		{
			if (!SceneResourceTracker.isNodeInScope(obj.getWorldLocation(), plane, spot, onlyNearSpot))
			{
				continue;
			}
			boolean isClosest = obj == closestObj;
			drawTileObjectHighlight(
				graphics,
				obj,
				style,
				isClosest ? closestBorder : borderColor,
				isClosest ? closestFill : fillColor,
				isClosest ? closestStroke : stroke,
				isClosest ? closestOutlineWidth : outlineWidth,
				feather
			);
		}

		for (NPC npc : tracker.getTrackedNpcs())
		{
			if (!SceneResourceTracker.isNodeInScope(npc.getWorldLocation(), plane, spot, onlyNearSpot))
			{
				continue;
			}
			boolean isClosest = npc == closestNpc;
			drawNpcHighlight(
				graphics,
				npc,
				style,
				isClosest ? closestBorder : borderColor,
				isClosest ? closestFill : fillColor,
				isClosest ? closestStroke : stroke,
				isClosest ? closestOutlineWidth : outlineWidth,
				feather
			);
		}
	}

	private void drawTileObjectHighlight(
		Graphics2D graphics,
		TileObject obj,
		HighlightStyle style,
		Color borderColor,
		Color fillColor,
		Stroke stroke,
		int outlineWidth,
		int feather)
	{
		if (style == HighlightStyle.OUTLINE || style == HighlightStyle.OUTLINE_AND_TILE)
		{
			modelOutlineRenderer.drawOutline(obj, outlineWidth, borderColor, feather);
		}
		if (style == HighlightStyle.HULL)
		{
			Shape clickbox = obj.getClickbox();
			if (clickbox != null)
			{
				OverlayUtil.renderPolygon(graphics, clickbox, borderColor, fillColor, stroke);
			}
		}
		if (style == HighlightStyle.TILE || style == HighlightStyle.OUTLINE_AND_TILE)
		{
			Polygon tilePoly = obj.getCanvasTilePoly();
			if (tilePoly != null)
			{
				OverlayUtil.renderPolygon(graphics, tilePoly, borderColor, fillColor, stroke);
			}
		}
	}

	private void drawNpcHighlight(
		Graphics2D graphics,
		NPC npc,
		HighlightStyle style,
		Color borderColor,
		Color fillColor,
		Stroke stroke,
		int outlineWidth,
		int feather)
	{
		if (style == HighlightStyle.OUTLINE || style == HighlightStyle.OUTLINE_AND_TILE)
		{
			modelOutlineRenderer.drawOutline(npc, outlineWidth, borderColor, feather);
		}
		if (style == HighlightStyle.HULL)
		{
			Shape hull = npc.getConvexHull();
			if (hull != null)
			{
				OverlayUtil.renderPolygon(graphics, hull, borderColor, fillColor, stroke);
			}
		}
		if (style == HighlightStyle.TILE || style == HighlightStyle.OUTLINE_AND_TILE)
		{
			Polygon tilePoly = npc.getCanvasTilePoly();
			if (tilePoly != null)
			{
				OverlayUtil.renderPolygon(graphics, tilePoly, borderColor, fillColor, stroke);
			}
		}
	}

	private void renderNearestBank(
		Graphics2D graphics,
		GatheringSpot spot,
		WorldPoint playerLoc,
		WorldView worldView,
		Stroke stroke)
	{
		Color bankColor = config.bankColor();
		Color bankFill = getBankFill(bankColor);
		boolean routingToBank = routeManager.getRouteDestination() == SpotRouteManager.RouteDestination.BANK;
		int bankOutlineWidth = routingToBank ? Math.min(5, config.outlineWidth() + 1) : config.outlineWidth();

		TileObject bankObj = tracker.findSpotBankObject(spot, playerLoc);
		if (bankObj != null)
		{
			modelOutlineRenderer.drawOutline(bankObj, bankOutlineWidth, bankColor, config.outlineFeather());
			Polygon poly = bankObj.getCanvasTilePoly();
			if (poly != null)
			{
				OverlayUtil.renderPolygon(graphics, poly, bankColor, bankFill, stroke);
			}

			if (config.showBankDistanceLabel() || routingToBank)
			{
				int dist = playerLoc.distanceTo2D(bankObj.getWorldLocation());
				BankInfo bankInfo = spot.getBank();
				String prefix = (bankInfo != null && bankInfo.hasBanking()) ? bankInfo.getType().getDisplayName() : "Bank";
				String label = (routingToBank ? "Target: " : "") + prefix + " (" + dist + "t)";
				Point textLoc = Perspective.getCanvasTextLocation(client, graphics, bankObj.getLocalLocation(), label, 40);
				if (textLoc != null)
				{
					OverlayUtil.renderTextLocation(graphics, textLoc, label, bankColor);
				}
			}
			return;
		}

		BankInfo bankInfo = spot.getBank();
		if (bankInfo != null && bankInfo.hasBanking() && bankInfo.getLocation() != null
			&& bankInfo.getLocation().getPlane() == worldView.getPlane())
		{
			LocalPoint local = LocalPoint.fromWorld(worldView, bankInfo.getLocation());
			if (local != null && worldView.contains(local))
			{
				Polygon poly = Perspective.getCanvasTilePoly(client, local);
				if (poly != null)
				{
					OverlayUtil.renderPolygon(graphics, poly, bankColor, bankFill, stroke);
				}
				if (config.showBankDistanceLabel() || routingToBank)
				{
					int dist = playerLoc.distanceTo2D(bankInfo.getLocation());
					String label = (routingToBank ? "Target: " : "") + bankInfo.getName() + " (" + dist + "t)";
					Point textLoc = Perspective.getCanvasTextLocation(client, graphics, local, label, 20);
					if (textLoc != null)
					{
						OverlayUtil.renderTextLocation(graphics, textLoc, label, bankColor);
					}
				}
			}
		}
	}

	private void renderDestinationMarker(
		Graphics2D graphics,
		GatheringSpot spot,
		WorldPoint playerLoc,
		WorldView worldView,
		Stroke stroke)
	{
		if (routeManager.getRouteDestination() != SpotRouteManager.RouteDestination.SPOT)
		{
			return;
		}
		WorldPoint spotLoc = spot.getLocation();
		if (spotLoc.getPlane() != worldView.getPlane())
		{
			return;
		}
		int dist = playerLoc.distanceTo2D(spotLoc);
		if (dist <= 6)
		{
			return;
		}
		LocalPoint local = LocalPoint.fromWorld(worldView, spotLoc);
		if (local == null || !worldView.contains(local))
		{
			return;
		}

		Color accent = config.resourceColor();
		Polygon poly = Perspective.getCanvasTilePoly(client, local);
		if (poly != null)
		{
			OverlayUtil.renderPolygon(graphics, poly, accent, getDestinationFill(accent), stroke);
		}
		String label = spot.getName() + " (" + dist + "t)";
		Point textLoc = Perspective.getCanvasTextLocation(client, graphics, local, label, 20);
		if (textLoc != null)
		{
			OverlayUtil.renderTextLocation(graphics, textLoc, label, accent);
		}
	}

	private Stroke getStroke(int width)
	{
		if (width != cachedStrokeWidth)
		{
			cachedStrokeWidth = width;
			cachedStroke = new BasicStroke((float) width);
			cachedClosestStroke = new BasicStroke((float) Math.min(5, width + 1));
		}
		return cachedStroke;
	}

	private Stroke getClosestStroke(int width)
	{
		getStroke(width);
		return cachedClosestStroke;
	}

	private Color getResourceFill(Color base)
	{
		if (!base.equals(cachedResourceColor))
		{
			cachedResourceColor = base;
			cachedResourceFill = new Color(base.getRed(), base.getGreen(), base.getBlue(), FILL_ALPHA);
			cachedDestFill = new Color(base.getRed(), base.getGreen(), base.getBlue(), DEST_FILL_ALPHA);
		}
		return cachedResourceFill;
	}

	private Color getClosestFill(Color base)
	{
		if (!base.equals(cachedClosestColor))
		{
			cachedClosestColor = base;
			cachedClosestFill = new Color(base.getRed(), base.getGreen(), base.getBlue(), FILL_ALPHA);
		}
		return cachedClosestFill;
	}

	private Color getDestinationFill(Color base)
	{
		getResourceFill(base);
		return cachedDestFill;
	}

	private Color getBankFill(Color base)
	{
		if (!base.equals(cachedBankColor))
		{
			cachedBankColor = base;
			cachedBankFill = new Color(base.getRed(), base.getGreen(), base.getBlue(), FILL_ALPHA);
		}
		return cachedBankFill;
	}
}

