package com.spotfinder.ranking;

import com.spotfinder.data.AccountSnapshot;
import com.spotfinder.data.BankInfo;
import com.spotfinder.data.BankType;
import com.spotfinder.data.DiaryTier;
import com.spotfinder.data.GatheringSkill;
import com.spotfinder.data.GatheringSpot;
import com.spotfinder.data.ResourceType;
import com.spotfinder.data.SpotCatalog;
import com.spotfinder.data.SpotRequirement;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Quest;
import net.runelite.api.Skill;
import net.runelite.api.coords.WorldPoint;

public final class SpotRanker
{
	public static final int MAX_BOOST_LEVELS = 5;

	private SpotRanker()
	{
	}

	public static EvaluatedSpot evaluate(GatheringSpot spot, AccountSnapshot account)
	{
		return evaluate(spot, account, RankOptions.builder().build());
	}

	public static EvaluatedSpot evaluate(GatheringSpot spot, AccountSnapshot account, RankOptions options)
	{
		List<String> missing = new ArrayList<>();
		SpotRequirement req = spot.getRequirements();
		ResourceType resource = spot.getResource();
		boolean hasNonSkillBlocker = false;
		int maxSkillDeficit = 0;

		if (account.isLoggedIn())
		{
			if (spot.isMembersOnly() && !account.isMembersWorld())
			{
				missing.add("Members world");
				hasNonSkillBlocker = true;
			}

			Map<Skill, Integer> skillReqs = req.getEffectiveSkillLevels(resource.getSkill(), resource.getRequiredLevel());
			for (Map.Entry<Skill, Integer> entry : skillReqs.entrySet())
			{
				if (entry.getValue() <= 1)
				{
					continue;
				}
				int current = account.getSkillLevel(entry.getKey());
				if (current < entry.getValue())
				{
					int deficit = entry.getValue() - current;
					maxSkillDeficit = Math.max(maxSkillDeficit, deficit);
					missing.add(entry.getValue() + " " + entry.getKey().getName() + " (have " + current + ")");
				}
			}

			if (req.getRequiredQuests() != null)
			{
				for (Quest quest : req.getRequiredQuests())
				{
					if (!account.hasCompletedQuest(quest))
					{
						missing.add("Quest: " + quest.getName());
						hasNonSkillBlocker = true;
					}
				}
			}

			if (req.getRequiredDiaries() != null)
			{
				for (DiaryTier diary : req.getRequiredDiaries())
				{
					if (!account.hasCompletedDiary(diary))
					{
						missing.add(diary.getDisplayName());
						hasNonSkillBlocker = true;
					}
				}
			}
		}

		UnlockStatus status;
		if (missing.isEmpty())
		{
			status = UnlockStatus.UNLOCKED;
		}
		else if (options.isShowBoostable() && !hasNonSkillBlocker && maxSkillDeficit > 0 && maxSkillDeficit <= MAX_BOOST_LEVELS)
		{
			status = UnlockStatus.BOOSTABLE;
		}
		else
		{
			status = UnlockStatus.LOCKED;
		}

		boolean bankUnlocked = isBankUnlocked(spot.getBank(), account);
		Set<String> favorites = options.getFavoriteIds();
		boolean favorite = favorites != null && favorites.contains(spot.getId());
		int distanceFromPlayer = computePlayerDistance(spot.getLocation(), account);
		AccountMode effectiveMode = resolveAccountMode(options.getAccountMode(), account);
		double score = computeBestOverallScore(spot, status, bankUnlocked, effectiveMode);

		return new EvaluatedSpot(
			spot,
			status,
			bankUnlocked,
			favorite,
			Collections.unmodifiableList(missing),
			status == UnlockStatus.BOOSTABLE ? maxSkillDeficit : 0,
			distanceFromPlayer,
			score
		);
	}

	public static List<EvaluatedSpot> rank(List<GatheringSpot> spots, AccountSnapshot account, RankOptions options)
	{
		List<EvaluatedSpot> evaluated = new ArrayList<>(spots.size());
		for (GatheringSpot spot : spots)
		{
			if (options.isF2pOnly() && spot.isMembersOnly())
			{
				continue;
			}
			if (!options.isIncludeWilderness() && spot.isWilderness())
			{
				continue;
			}
			EvaluatedSpot item = evaluate(spot, account, options);
			if (options.isHideLocked())
			{
				boolean allowed = item.isUnlocked()
					|| (options.isShowBoostable() && options.isIncludeBoostableInUnlocked() && item.isBoostable());
				if (!allowed)
				{
					continue;
				}
			}
			evaluated.add(item);
		}

		evaluated.sort(comparatorFor(options.getSortMode()));
		return evaluated;
	}

	public static ResourceType recommendBestResource(
		GatheringSkill skill,
		AccountSnapshot account,
		RankOptions baseOptions)
	{
		ResourceType[] resources = ResourceType.forSkill(skill);
		ResourceType best = resources.length > 0 ? resources[0] : null;
		int bestLevel = -1;

		RankOptions unlockedOnly = RankOptions.builder()
			.sortMode(SortMode.BEST_OVERALL)
			.hideLocked(true)
			.showBoostable(false)
			.includeBoostableInUnlocked(false)
			.f2pOnly(baseOptions.isF2pOnly())
			.includeWilderness(baseOptions.isIncludeWilderness())
			.accountMode(baseOptions.getAccountMode())
			.build();

		for (ResourceType resource : resources)
		{
			if (baseOptions.isF2pOnly() && resource.isMembersOnly())
			{
				continue;
			}
			List<EvaluatedSpot> unlockedSpots = rank(
				SpotCatalog.getSpotsForResource(resource),
				account,
				unlockedOnly
			);
			if (!unlockedSpots.isEmpty() && resource.getRequiredLevel() >= bestLevel)
			{
				bestLevel = resource.getRequiredLevel();
				best = resource;
			}
		}
		return best;
	}

	public static AccountMode resolveAccountMode(AccountMode configured, AccountSnapshot account)
	{
		if (configured != null && configured != AccountMode.AUTO)
		{
			return configured;
		}
		if (!account.isLoggedIn())
		{
			return AccountMode.MAIN;
		}
		if (account.isUltimateIronman())
		{
			return AccountMode.UIM;
		}
		if (account.isIronmanFamily())
		{
			return AccountMode.IRONMAN;
		}
		return AccountMode.MAIN;
	}

	public static boolean isBankUnlocked(BankInfo bank, AccountSnapshot account)
	{
		if (bank == null || !bank.hasBanking())
		{
			return false;
		}
		if (!account.isLoggedIn())
		{
			return true;
		}
		boolean hasDiaryReq = bank.getBankDiaryRequirement() != null;
		boolean hasSkillAlt = bank.getBankAltSkill() != null && bank.getBankAltSkillLevel() > 0;
		if (!hasDiaryReq && !hasSkillAlt)
		{
			return true;
		}
		boolean meetsDiary = hasDiaryReq && account.hasCompletedDiary(bank.getBankDiaryRequirement());
		boolean meetsSkill = hasSkillAlt && account.getSkillLevel(bank.getBankAltSkill()) >= bank.getBankAltSkillLevel();
		return meetsDiary || meetsSkill;
	}

	static int computePlayerDistance(WorldPoint spotPoint, AccountSnapshot account)
	{
		if (!account.isLoggedIn() || account.getPlayerLocation() == null || spotPoint == null)
		{
			return -1;
		}
		WorldPoint player = account.getPlayerLocation();
		if (player.getPlane() != spotPoint.getPlane())
		{
			return -1;
		}
		// Underground/instanced areas live at y >= 4500; straight-line distance across surface<->dungeon is misleading.
		boolean playerUnderground = player.getY() >= 4500;
		boolean spotUnderground = spotPoint.getY() >= 4500;
		if (playerUnderground != spotUnderground)
		{
			return -1;
		}
		return player.distanceTo2D(spotPoint);
	}

	private static double computeBestOverallScore(
		GatheringSpot spot,
		UnlockStatus status,
		boolean bankUnlocked,
		AccountMode accountMode)
	{
		double score = 0.0;
		score += Math.min(spot.getNodeCount(), 20) * 1.8;

		// For grouped categories (e.g. Agility courses or Runecraft altars), prefer higher unlocked tiers.
		Map<Skill, Integer> extraLevels = spot.getRequirements() != null ? spot.getRequirements().getExtraSkillLevels() : null;
		if (extraLevels != null)
		{
			Integer spotPrimaryLevel = extraLevels.get(spot.getResource().getSkill().getApiSkill());
			if (spotPrimaryLevel != null && spotPrimaryLevel > spot.getResource().getRequiredLevel())
			{
				score += spotPrimaryLevel * 0.65;
			}
		}

		BankInfo bank = spot.getBank();
		if (accountMode == AccountMode.UIM)
		{
			// UIMs cannot use standard banks, so weight node density and perks instead of bank distance.
			score += Math.min(spot.getNodeCount(), 20) * 1.2;
		}
		else if (bank != null && bank.hasBanking() && bankUnlocked)
		{
			double bankBonus = Math.max(0.0, 48.0 - (bank.getDistanceTiles() * 0.45));
			if (bank.getType() == BankType.DEPOSIT_BOX)
			{
				bankBonus *= 0.92;
			}
			if (accountMode == AccountMode.IRONMAN)
			{
				bankBonus *= 1.25;
			}
			score += bankBonus;
		}
		else if (bank != null && bank.hasBanking())
		{
			score += 4.0;
		}

		if (spot.isGuildBoost())
		{
			score += 22.0;
		}

		if (spot.isIronmanHighlight() && (accountMode == AccountMode.IRONMAN || accountMode == AccountMode.UIM))
		{
			score += 14.0;
		}

		if (spot.isWilderness())
		{
			score -= 10.0;
		}

		if (status == UnlockStatus.BOOSTABLE)
		{
			score -= 300.0;
		}
		else if (status == UnlockStatus.LOCKED)
		{
			score -= 1000.0;
		}

		return score;
	}

	private static int statusOrder(UnlockStatus status)
	{
		switch (status)
		{
			case UNLOCKED:
				return 0;
			case BOOSTABLE:
				return 1;
			case LOCKED:
			default:
				return 2;
		}
	}

	private static Comparator<EvaluatedSpot> comparatorFor(SortMode mode)
	{
		Comparator<EvaluatedSpot> favoritesFirst = Comparator.comparing(EvaluatedSpot::isFavorite).reversed();
		Comparator<EvaluatedSpot> byStatus = Comparator.comparingInt(e -> statusOrder(e.getUnlockStatus()));
		Comparator<EvaluatedSpot> byScore = Comparator.comparingDouble(EvaluatedSpot::getScore).reversed();
		Comparator<EvaluatedSpot> byName = Comparator.comparing(e -> e.getSpot().getName());

		switch (mode)
		{
			case CLOSEST_BANK:
				return favoritesFirst
					.thenComparing(byStatus)
					.thenComparing(e -> !e.isBankUnlocked())
					.thenComparingInt(e -> e.isBankUnlocked() ? e.getSpot().getBank().getDistanceTiles() : Integer.MAX_VALUE)
					.thenComparing(byScore)
					.thenComparing(byName);

			case MOST_NODES:
				return favoritesFirst
					.thenComparing(byStatus)
					.thenComparing(Comparator.comparingInt((EvaluatedSpot e) -> e.getSpot().getNodeCount()).reversed())
					.thenComparing(Comparator.comparing((EvaluatedSpot e) -> e.getSpot().isGuildBoost()).reversed())
					.thenComparing(byScore)
					.thenComparing(byName);

			case NEAREST_TO_ME:
				return favoritesFirst
					.thenComparing(byStatus)
					.thenComparing(e -> !e.hasPlayerDistance())
					.thenComparingInt(e -> e.hasPlayerDistance() ? e.getDistanceFromPlayer() : Integer.MAX_VALUE)
					.thenComparing(byScore)
					.thenComparing(byName);

			case BEST_OVERALL:
			default:
				return favoritesFirst
					.thenComparing(byStatus)
					.thenComparing(byScore)
					.thenComparing(byName);
		}
	}
}

