class SpotCardPanel extends JPanel
{
	private static final Color ACCENT_TEAL = new Color(0, 204, 156);
	private static final Color CARD_BORDER = new Color(56, 56, 60);
	private static final Color BTN_BG = new Color(46, 46, 50);
	private static final Color BTN_HOVER_BG = new Color(62, 62, 68);
	private static final Color BTN_BORDER = new Color(72, 72, 78);
	private static final Color BADGE_UNLOCKED_BG = new Color(30, 88, 56);
	private static final Color BADGE_BOOSTABLE_BG = new Color(118, 86, 24);
	private static final Color BADGE_LOCKED_BG = new Color(112, 38, 38);
	private static final Color BADGE_PREVIEW_BG = new Color(64, 64, 72);
	private static final Color BADGE_F2P_BG = new Color(36, 78, 118);
	private static final Color BADGE_P2P_BG = new Color(96, 68, 28);
	private static final Color BADGE_BOOST_BG = new Color(26, 92, 108);
	private static final Color BADGE_IM_BG = new Color(74, 78, 88);
	private static final Color BADGE_WILDY_BG = new Color(138, 46, 22);
	private static final Color MUTED_TEXT = new Color(168, 168, 176);
	private static final Color LOCKED_TEXT = new Color(238, 134, 134);
	private static final Color BOOSTABLE_TEXT = new Color(248, 214, 126);
	private static final Color BANK_GOLD = new Color(245, 192, 72);
	private static final Color BANK_GOLD_HOVER = new Color(255, 208, 102);

	private static final Icon STAR_FILLED = new StarIcon(12, BANK_GOLD, true);
	private static final Icon STAR_OUTLINE = new StarIcon(12, new Color(128, 128, 136), false);

	SpotCardPanel(
		int rank,
		EvaluatedSpot evaluated,
		boolean loggedIn,
		boolean active,
		SpotRouteManager.RouteDestination activeDestination,
		AccountMode effectiveAccountMode,
		boolean showResourcePrefix,
		BiConsumer<GatheringSpot, SpotRouteManager.RouteDestination> onRoute,
		Runnable onDeselect,
		Consumer<String> onToggleFavorite)
	{
		GatheringSpot spot = evaluated.getSpot();
		boolean activeBankRoute = active && activeDestination == SpotRouteManager.RouteDestination.BANK;

		setLayout(new GridBagLayout());
		setBackground(ColorScheme.DARKER_GRAY_COLOR);
		Color cardBorderColor = active
			? (activeBankRoute ? BANK_GOLD : ACCENT_TEAL)
			: CARD_BORDER;
		setBorder(new CompoundBorder(
			new LineBorder(cardBorderColor, active ? 2 : 1),
			new EmptyBorder(7, 8, 7, 8)
		));

		GridBagConstraints c = new GridBagConstraints();
		c.gridx = 0;
		c.gridy = 0;
		c.weightx = 1.0;
		c.fill = GridBagConstraints.HORIZONTAL;
		c.anchor = GridBagConstraints.NORTHWEST;

		JPanel header = new JPanel(new BorderLayout(4, 0));
		header.setOpaque(false);

		JLabel rankLabel = new JLabel("#" + rank);
		rankLabel.setFont(FontManager.getRunescapeBoldFont());
		rankLabel.setForeground(active ? cardBorderColor : ColorScheme.BRAND_ORANGE);
		rankLabel.setVerticalAlignment(JLabel.TOP);
		header.add(rankLabel, BorderLayout.WEST);

		String titleText = showResourcePrefix
			? spot.getResource().getDisplayName() + " - " + spot.getName()
			: spot.getName();
		JTextArea nameArea = createWrappedText(titleText, FontManager.getRunescapeBoldFont(), Color.WHITE);
		header.add(nameArea, BorderLayout.CENTER);

		JButton favBtn = new JButton(evaluated.isFavorite() ? STAR_FILLED : STAR_OUTLINE);
		favBtn.setOpaque(false);
		favBtn.setContentAreaFilled(false);
		favBtn.setBorderPainted(false);
		favBtn.setFocusPainted(false);
		favBtn.setBorder(new EmptyBorder(0, 2, 0, 0));
		favBtn.setVerticalAlignment(JButton.TOP);
		favBtn.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		favBtn.setToolTipText(evaluated.isFavorite() ? "Unpin favorite spot" : "Pin spot to top of list");
		favBtn.addActionListener(e -> onToggleFavorite.accept(spot.getId()));
		header.add(favBtn, BorderLayout.EAST);

		add(header, c);

		c.gridy++;
		c.insets = new Insets(1, 0, 4, 0);
		JLabel regionLabel = new JLabel(spot.getRegion());
		regionLabel.setFont(FontManager.getRunescapeSmallFont());
		regionLabel.setForeground(MUTED_TEXT);
		add(regionLabel, c);

		c.gridy++;
		c.insets = new Insets(0, 0, 5, 0);
		JPanel badges = new JPanel();
		badges.setLayout(new BoxLayout(badges, BoxLayout.X_AXIS));
		badges.setOpaque(false);

		if (!loggedIn)
		{
			addBadge(badges, "PREVIEW", BADGE_PREVIEW_BG, Color.LIGHT_GRAY);
		}
		else if (evaluated.getUnlockStatus() == UnlockStatus.UNLOCKED)
		{
			addBadge(badges, "UNLOCKED", BADGE_UNLOCKED_BG, new Color(185, 250, 205));
		}
		else if (evaluated.getUnlockStatus() == UnlockStatus.BOOSTABLE)
		{
			addBadge(badges, "BOOST +" + evaluated.getMaxBoostNeeded(), BADGE_BOOSTABLE_BG, BOOSTABLE_TEXT);
		}
		else
		{
			addBadge(badges, "LOCKED", BADGE_LOCKED_BG, new Color(255, 195, 195));
		}

		if (spot.isMembersOnly())
		{
			addBadge(badges, "P2P", BADGE_P2P_BG, new Color(255, 224, 150));
		}
		else
		{
			addBadge(badges, "F2P", BADGE_F2P_BG, new Color(180, 220, 255));
		}

		if (spot.isGuildBoost())
		{
			addBadge(badges, "PERK", BADGE_BOOST_BG, new Color(165, 240, 255));
		}
		if (spot.isIronmanHighlight() && (effectiveAccountMode == AccountMode.IRONMAN || effectiveAccountMode == AccountMode.UIM))
		{
			addBadge(badges, "IM", BADGE_IM_BG, new Color(226, 232, 240));
		}
		if (spot.isWilderness())
		{
			addBadge(badges, "WILDY", BADGE_WILDY_BG, new Color(255, 210, 180));
		}
		badges.add(Box.createHorizontalGlue());
		add(badges, c);

		StringBuilder metrics = new StringBuilder();
		metrics.append(spot.getNodeCount()).append(spot.getNodeCount() == 1 ? " node" : " nodes");

		BankInfo bank = spot.getBank();
		if (bank != null && bank.hasBanking())
		{
			String bankShort = bank.getType() == BankType.DEPOSIT_BOX ? "Deposit" : "Bank";
			metrics.append("  |  ").append(bankShort).append(": ").append(bank.getDistanceTiles()).append("t");
		}
		else
		{
			metrics.append("  |  No bank");
		}

		if (evaluated.hasPlayerDistance())
		{
			metrics.append("  |  You: ").append(evaluated.getDistanceFromPlayer()).append("t");
		}

		c.gridy++;
		c.insets = new Insets(0, 0, 2, 0);
		add(createWrappedText(metrics.toString(), FontManager.getRunescapeSmallFont(), Color.LIGHT_GRAY), c);

		if (bank != null && bank.hasBanking())
		{
			String bankDetail = bank.getName();
			if (!evaluated.isBankUnlocked())
			{
				String reqSummary = bank.getBankRequirementSummary();
				if (!reqSummary.isEmpty())
				{
					bankDetail += " (needs " + reqSummary + ")";
				}
			}
			c.gridy++;
			c.insets = new Insets(0, 0, 2, 0);
			add(createWrappedText(
				bankDetail,
				FontManager.getRunescapeSmallFont(),
				evaluated.isBankUnlocked() ? BANK_GOLD : LOCKED_TEXT
			), c);
		}

		if (!evaluated.isUnlocked() && !evaluated.getMissingRequirements().isEmpty())
		{
			String prefix = evaluated.isBoostable() ? "Boostable: " : "Needs: ";
			String joined = prefix + String.join(", ", evaluated.getMissingRequirements());
			c.gridy++;
			c.insets = new Insets(2, 0, 2, 0);
			add(createWrappedText(
				joined,
				FontManager.getRunescapeSmallFont(),
				evaluated.isBoostable() ? BOOSTABLE_TEXT : LOCKED_TEXT
			), c);
		}

		String extraNote = spot.getRequirements() != null ? spot.getRequirements().getExtraNote() : null;
		String tip = spot.getTip();
		String detailLine = (tip != null && !tip.isEmpty()) ? tip : extraNote;
		if (detailLine != null && !detailLine.isEmpty())
		{
			c.gridy++;
			c.insets = new Insets(2, 0, 0, 0);
			add(createWrappedText(detailLine, FontManager.getRunescapeSmallFont(), MUTED_TEXT), c);
		}

		c.gridy++;
		c.insets = new Insets(7, 0, 0, 0);
		JPanel actions = new JPanel(new GridLayout(1, 3, 4, 0));
		actions.setOpaque(false);

		boolean activeSpotRoute = active && !activeBankRoute;
		JButton routeBtn = createActionButton(
			active ? "Deselect" : "Route",
			activeSpotRoute ? ACCENT_TEAL : BTN_BG,
			activeSpotRoute ? new Color(24, 224, 174) : BTN_HOVER_BG,
			activeSpotRoute ? Color.BLACK : Color.WHITE,
			activeSpotRoute ? ACCENT_TEAL : BTN_BORDER
		);
		routeBtn.setToolTipText(active
			? "Deselect this spot and clear highlights and route"
			: "Highlight this spot's nodes, pin on World Map, and route via Shortest Path");
		routeBtn.addActionListener(e -> {
			if (active)
			{
				onDeselect.run();
			}
			else
			{
				onRoute.accept(spot, SpotRouteManager.RouteDestination.SPOT);
			}
		});
		actions.add(routeBtn);

		boolean canRouteBank = bank != null && bank.hasBanking();
		JButton bankBtn = createActionButton(
			activeBankRoute ? "Banking" : "Bank",
			activeBankRoute ? BANK_GOLD : BTN_BG,
			activeBankRoute ? BANK_GOLD_HOVER : BTN_HOVER_BG,
			activeBankRoute ? Color.BLACK : (canRouteBank ? BANK_GOLD : Color.GRAY),
			activeBankRoute ? BANK_GOLD : BTN_BORDER
		);
		bankBtn.setEnabled(canRouteBank);
		bankBtn.setToolTipText(canRouteBank
			? (activeBankRoute ? "Routing to " + bank.getName() + " (click to re-center)" : "Route to " + bank.getName())
			: "No nearby bank for this spot");
		bankBtn.addActionListener(e -> onRoute.accept(spot, SpotRouteManager.RouteDestination.BANK));
		actions.add(bankBtn);

		JButton wikiBtn = createActionButton("Wiki", BTN_BG, BTN_HOVER_BG, Color.LIGHT_GRAY, BTN_BORDER);
		wikiBtn.setToolTipText("Open " + spot.getResource().getDisplayName() + " on the OSRS Wiki");
		wikiBtn.addActionListener(e -> LinkBrowser.browse(spot.getResource().getWikiUrl()));
		actions.add(wikiBtn);

		add(actions, c);
	}

	private static void addBadge(JPanel row, String text, Color bg, Color fg)
	{
		if (row.getComponentCount() > 0)
		{
			row.add(Box.createHorizontalStrut(4));
		}
		JLabel label = new JLabel(text);
		label.setOpaque(true);
		label.setBackground(bg);
		label.setForeground(fg);
		label.setFont(FontManager.getRunescapeSmallFont().deriveFont(Font.BOLD, 10f));
		label.setBorder(new EmptyBorder(1, 4, 1, 4));
		row.add(label);
	}

	static JTextArea createWrappedText(String text, Font font, Color fg)
	{
		JTextArea area = new JTextArea(text);
		area.setEditable(false);
		area.setFocusable(false);
		area.setOpaque(false);
		area.setLineWrap(true);
		area.setWrapStyleWord(true);
		area.setFont(font);
		area.setForeground(fg);
		area.setBorder(null);
		// Seed width so initial preferred height wraps accurately before first viewport layout pass.
		area.setSize(new Dimension(170, Short.MAX_VALUE));
		area.setMinimumSize(new Dimension(0, 0));
		return area;
	}

	static JButton createActionButton(String text, Color bg, Color hoverBg, Color fg, Color borderColor)
	{
		JButton btn = new JButton(text);
		btn.setFont(FontManager.getRunescapeSmallFont());
		btn.setBackground(bg);
		btn.setForeground(fg);
		btn.setOpaque(true);
		btn.setFocusPainted(false);
		btn.setBorder(new CompoundBorder(
			new LineBorder(borderColor, 1),
			new EmptyBorder(3, 4, 3, 4)
		));
		btn.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		btn.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				if (btn.isEnabled())
				{
					btn.setBackground(hoverBg);
				}
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				btn.setBackground(bg);
			}
		});
		return btn;
	}

	private static final class StarIcon implements Icon
	{
		private final int size;
		private final Color color;
		private final boolean filled;

		StarIcon(int size, Color color, boolean filled)
		{
			this.size = size;
			this.color = color;
			this.filled = filled;
		}

		@Override
		public void paintIcon(Component c, Graphics g, int x, int y)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			double cx = x + size / 2.0;
			double cy = y + size / 2.0;
			double outerR = size * 0.48;
			double innerR = size * 0.21;
			Path2D star = new Path2D.Double();
			for (int i = 0; i < 10; i++)
			{
				double angle = Math.toRadians(-90 + i * 36);
				double r = (i % 2 == 0) ? outerR : innerR;
				double px = cx + Math.cos(angle) * r;
				double py = cy + Math.sin(angle) * r;
				if (i == 0)
				{
					star.moveTo(px, py);
				}
				else
				{
					star.lineTo(px, py);
				}
			}
			star.closePath();
			g2.setColor(color);
			if (filled)
			{
				g2.fill(star);
			}
			else
			{
				g2.draw(star);
			}
			g2.dispose();
		}

		@Override
		public int getIconWidth()
		{
			return size;
		}

		@Override
		public int getIconHeight()
		{
			return size;
		}
	}
}

