	public void updateAccountState(AccountSnapshot snapshot)
	{
		SwingUtilities.invokeLater(() -> {
			this.accountSnapshot = snapshot != null ? snapshot : AccountSnapshot.LOGGED_OUT;
			updateAccountStatusHeader();
			resourceCombo.repaint();
			rebuildSpotList();
		});
	}

	public void updateActiveSpot(GatheringSpot spot, SpotRouteManager.RouteDestination destination, boolean shortestPathAvailable)
	{
		SwingUtilities.invokeLater(() -> {
			this.activeSpot = spot;
			this.activeDestination = destination != null ? destination : SpotRouteManager.RouteDestination.SPOT;
			this.shortestPathAvailable = shortestPathAvailable;
			updateActiveBanner();
			rebuildSpotList();
		});
	}

	public void onConfigUpdated()
	{
		SwingUtilities.invokeLater(() -> {
			this.globalHighlight = !config.highlightOnlyNearSpot();
			updateFilterPillStyles();
			updateAccountStatusHeader();
			rebuildSpotList();
		});
	}

	private ResourceType loadPersistedState()
	{
		selectedSkill = parseEnum(configManager.getConfiguration(SpotFinderConfig.GROUP, KEY_LAST_SKILL), GatheringSkill.class, GatheringSkill.WOODCUTTING);
		selectedSortMode = parseEnum(configManager.getConfiguration(SpotFinderConfig.GROUP, KEY_LAST_SORT), SortMode.class, config.defaultSortMode());
		sortCombo.setSelectedItem(selectedSortMode);

		hideLockedOnly = parseBool(configManager.getConfiguration(SpotFinderConfig.GROUP, KEY_FILTER_UNLOCKED), config.hideLockedByDefault());
		f2pOnly = parseBool(configManager.getConfiguration(SpotFinderConfig.GROUP, KEY_FILTER_F2P), false);
		includeWilderness = parseBool(configManager.getConfiguration(SpotFinderConfig.GROUP, KEY_FILTER_WILDY), config.includeWildernessByDefault());
		globalHighlight = !config.highlightOnlyNearSpot();

		favoriteIds.clear();
		String savedFavs = configManager.getConfiguration(SpotFinderConfig.GROUP, KEY_FAVORITES);
		if (savedFavs != null && !savedFavs.isEmpty())
		{
			for (String id : savedFavs.split(","))
			{
				String trimmed = id.trim();
				if (!trimmed.isEmpty())
				{
					favoriteIds.add(trimmed);
				}
			}
		}

		ResourceType savedResource = parseEnum(configManager.getConfiguration(SpotFinderConfig.GROUP, KEY_LAST_RESOURCE), ResourceType.class, ResourceType.OAK_TREE);
		return savedResource.getSkill() == selectedSkill ? savedResource : ResourceType.forSkill(selectedSkill)[0];
	}

	private void persistString(String key, String value)
	{
		if (configManager != null)
		{
			configManager.setConfiguration(SpotFinderConfig.GROUP, key, value);
		}
	}

	private void persistBool(String key, boolean value)
	{
		if (configManager != null)
		{
			configManager.setConfiguration(SpotFinderConfig.GROUP, key, value);
		}
	}

