	private static void applyPillStyle(JButton btn, boolean active, Color onBg, Color onBorder, Color onText)
	{
		btn.setBackground(active ? onBg : PILL_OFF_BG);
		btn.setForeground(active ? onText : Color.LIGHT_GRAY);
		btn.setFont(active
			? FontManager.getRunescapeSmallFont().deriveFont(Font.BOLD, 11f)
			: FontManager.getRunescapeSmallFont().deriveFont(11f));
