	private void selectSkill(GatheringSkill skill)
	{
		this.selectedSkill = skill;
		persistString(KEY_LAST_SKILL, skill.name());
		updateSkillTabStyles();
		updateAccountStatusHeader();

		ResourceType preferred = SpotRanker.recommendBestResource(skill, accountSnapshot, buildRankOptions());
		populateResourceCombo(skill, preferred);
		if (preferred != null)
		{
			persistString(KEY_LAST_RESOURCE, preferred.name());
		}
		rebuildSpotList();
	}

	private void selectBestResourceForLevel()
	{
		searchField.setText("");
		ResourceType best = SpotRanker.recommendBestResource(selectedSkill, accountSnapshot, buildRankOptions());
		if (best != null)
		{
			updatingControls = true;
			resourceCombo.setSelectedItem(best);
			updatingControls = false;
			persistString(KEY_LAST_RESOURCE, best.name());
			rebuildSpotList();
		}
	}

	private void toggleFavorite(String spotId)
	{
		if (!favoriteIds.remove(spotId))
		{
			favoriteIds.add(spotId);
		}
		persistString(KEY_FAVORITES, String.join(",", favoriteIds));
		rebuildSpotList();
	}

	private void populateResourceCombo(GatheringSkill skill, ResourceType initialSelection)
	{
		updatingControls = true;
		ResourceType[] items = ResourceType.forSkill(skill);
		resourceCombo.setModel(new DefaultComboBoxModel<>(items));
		if (initialSelection != null && initialSelection.getSkill() == skill)
		{
			resourceCombo.setSelectedItem(initialSelection);
		}
		else if (items.length > 0)
		{
			resourceCombo.setSelectedIndex(0);
		}
		updatingControls = false;
	}

