	private void updateAccountStatusHeader()
	{
		if (!accountSnapshot.isLoggedIn())
		{
			accountStatusLabel.setText("Not logged in - showing all spots");
			accountStatusLabel.setForeground(Color.GRAY);
			return;
		}
		String worldTag = accountSnapshot.isMembersWorld() ? "P2P" : "F2P";
		String acctTag = accountSnapshot.getAccountTypeShortLabel();
		String prefix = acctTag.isEmpty() ? worldTag : (worldTag + " " + acctTag);

		if (selectedSkill == GatheringSkill.STATIONS)
		{
			accountStatusLabel.setText(prefix + "  |  Skilling Stations");
		}
		else
		{
			int skillLv = accountSnapshot.getSkillLevel(selectedSkill.getApiSkill());
			accountStatusLabel.setText(prefix + "  |  " + selectedSkill.getDisplayName() + " Lv " + skillLv);
		}
		accountStatusLabel.setForeground(ACCENT_TEAL_TEXT);
	}

	private void updateActiveBanner()
	{
		if (activeSpot == null)
		{
			activeBanner.setVisible(false);
			return;
		}
		boolean routingBank = activeDestination == SpotRouteManager.RouteDestination.BANK && activeSpot.getBank().hasBanking();
		String targetText = routingBank
			? "Routing to Bank: " + activeSpot.getBank().getName()
			: "Active: " + activeSpot.getResource().getDisplayName() + " - " + activeSpot.getName();

		activeBanner.setBorder(new CompoundBorder(
			new MatteBorder(1, 3, 1, 1, routingBank ? BANK_GOLD : ACCENT_TEAL),
			new EmptyBorder(6, 7, 6, 7)
		));
		activeBannerText.setText(targetText);
		if (shortestPathAvailable)
		{
			activeRouteHint.setText("Shortest Path route + World Map pin active");
			activeRouteHint.setForeground(ACCENT_TEAL_TEXT);
		}
		else
		{
			activeRouteHint.setText("World Map pin + minimap arrow active. Install Shortest Path in Plugin Hub for turn-by-turn paths.");
			activeRouteHint.setForeground(BANK_GOLD);
		}
		if (routingBank)
		{
			activeBankBtn.setText("Spot");
			activeBankBtn.setEnabled(true);
			activeBankBtn.setForeground(ACCENT_TEAL_TEXT);
			activeBankBtn.setToolTipText("Route back to " + activeSpot.getName());
		}
		else
		{
			activeBankBtn.setText("Bank");
			boolean hasBank = activeSpot.getBank().hasBanking();
			activeBankBtn.setEnabled(hasBank);
			activeBankBtn.setForeground(hasBank ? BANK_GOLD : Color.GRAY);
			activeBankBtn.setToolTipText(hasBank ? "Route to " + activeSpot.getBank().getName() : "No nearby bank");
		}
		activeBanner.setVisible(true);
	}

	private RankOptions buildRankOptions()
	{
		return RankOptions.builder()
			.sortMode(getSelectedSortMode())
			.hideLocked(hideLockedOnly)
			.showBoostable(config.showBoostableSpots())
			.includeBoostableInUnlocked(config.includeBoostableInUnlocked())
			.f2pOnly(f2pOnly)
			.includeWilderness(includeWilderness)
			.accountMode(config.accountMode())
			.favoriteIds(favoriteIds)
			.build();
	}

	private void rebuildSpotList()
	{
		spotListPanel.removeAll();

		String query = searchField.getText() != null ? searchField.getText().trim().toLowerCase(Locale.ROOT) : "";
		boolean isSearching = !query.isEmpty();

		List<GatheringSpot> candidates;
		if (isSearching)
		{
			candidates = filterBySearch(SpotCatalog.getSpotsForSkill(selectedSkill), query);
			if (candidates.isEmpty())
			{
				candidates = filterBySearch(SpotCatalog.getAllSpots(), query);
			}
		}
		else
		{
			ResourceType selectedResource = (ResourceType) resourceCombo.getSelectedItem();
			candidates = selectedResource != null
				? SpotCatalog.getSpotsForResource(selectedResource)
				: SpotCatalog.getSpotsForSkill(selectedSkill);
		}

		RankOptions options = buildRankOptions();
		AccountMode effectiveMode = SpotRanker.resolveAccountMode(options.getAccountMode(), accountSnapshot);
		List<EvaluatedSpot> ranked = SpotRanker.rank(candidates, accountSnapshot, options);

		GridBagConstraints c = new GridBagConstraints();
		c.gridx = 0;
		c.gridy = 0;
		c.weightx = 1.0;
		c.fill = GridBagConstraints.HORIZONTAL;
		c.anchor = GridBagConstraints.NORTH;

		if (ranked.isEmpty())
		{
			resultCountLabel.setText("0 spots matched");
			JTextArea empty = SpotCardPanel.createWrappedText(
				"No spots match your current filters. Try toggling Unlocked or F2P off, or clearing search.",
				FontManager.getRunescapeSmallFont(),
				Color.GRAY
			);
			empty.setBorder(new EmptyBorder(18, 8, 18, 8));
			spotListPanel.add(empty, c);
		}
		else
		{
			long unlockedCount = ranked.stream().filter(EvaluatedSpot::isUnlocked).count();
			long boostableCount = ranked.stream().filter(EvaluatedSpot::isBoostable).count();
			if (accountSnapshot.isLoggedIn())
			{
				String summary = ranked.size() + " spots (" + unlockedCount + " unlocked";
				if (boostableCount > 0)
				{
					summary += ", " + boostableCount + " boostable";
				}
				summary += ")";
				resultCountLabel.setText(summary);
			}
			else
			{
				resultCountLabel.setText(ranked.size() + " spots");
			}

			int rank = 1;
			for (EvaluatedSpot evaluated : ranked)
			{
				boolean isActive = activeSpot != null && activeSpot.getId().equals(evaluated.getSpot().getId());
				SpotCardPanel card = new SpotCardPanel(
					rank++,
					evaluated,
					accountSnapshot.isLoggedIn(),
					isActive,
					activeDestination,
					effectiveMode,
					isSearching,
					onSelectSpot,
					onClearRoute,
					this::toggleFavorite
				);
				c.insets = new Insets(0, 0, 6, 0);
				spotListPanel.add(card, c);
				c.gridy++;
			}
		}

		spotListPanel.revalidate();
		spotListPanel.repaint();
	}

	private static List<GatheringSpot> filterBySearch(List<GatheringSpot> source, String query)
	{
		List<GatheringSpot> matches = new ArrayList<>();
		for (GatheringSpot spot : source)
		{
			if (contains(spot.getName(), query)
				|| contains(spot.getRegion(), query)
				|| contains(spot.getResource().getDisplayName(), query)
				|| contains(spot.getResource().getSkill().getDisplayName(), query)
				|| (spot.getBank() != null && contains(spot.getBank().getName(), query))
				|| contains(spot.getTip(), query))
			{
				matches.add(spot);
			}
		}
		return matches;
	}

	private static boolean contains(String field, String query)
	{
		return field != null && field.toLowerCase(Locale.ROOT).contains(query);
	}

	private static <E extends Enum<E>> E parseEnum(String value, Class<E> enumClass, E fallback)
	{
		if (value == null || value.isEmpty())
		{
			return fallback;
		}
		try
		{
			return Enum.valueOf(enumClass, value);
		}
		catch (IllegalArgumentException ex)
		{
			return fallback;
		}
	}

	private static boolean parseBool(String value, boolean fallback)
	{
		if (value == null || value.isEmpty())
		{
			return fallback;
		}
		return Boolean.parseBoolean(value);
	}

	private static Image scalePreservingAspect(BufferedImage src, int maxSize)
	{
		int w = src.getWidth();
		int h = src.getHeight();
		if (w <= maxSize && h <= maxSize)
		{
			return src;
		}
		double scale = Math.min((double) maxSize / w, (double) maxSize / h);
		int targetW = Math.max(1, (int) Math.round(w * scale));
		int targetH = Math.max(1, (int) Math.round(h * scale));
		return src.getScaledInstance(targetW, targetH, Image.SCALE_SMOOTH);
	}

	private ImageIcon getResourceIcon(ResourceType resource)
	{
		ImageIcon cached = resourceIcons.get(resource);
		if (cached != null)
		{
			return cached;
		}
		AsyncBufferedImage img = itemManager.getImage(resource.getIconItemId());
		if (img == null)
		{
			return null;
		}
		ImageIcon icon = new ImageIcon(img.getScaledInstance(18, 18, Image.SCALE_SMOOTH));
		resourceIcons.put(resource, icon);
		img.onLoaded(() -> SwingUtilities.invokeLater(() -> {
			resourceIcons.put(resource, new ImageIcon(img.getScaledInstance(18, 18, Image.SCALE_SMOOTH)));
			resourceCombo.repaint();
		}));
		return icon;
	}

