	private class ResourceCellRenderer extends DefaultListCellRenderer
	{
		@Override
		public Component getListCellRendererComponent(
			JList<?> list,
			Object value,
			int index,
			boolean isSelected,
			boolean cellHasFocus)
		{
			super.getListCellRendererComponent(list, value, index, isSelected, cellHasFocus);
			if (value instanceof ResourceType)
			{
				ResourceType resource = (ResourceType) value;
				String label = resource.getSkill() == GatheringSkill.STATIONS
					? resource.getDisplayName()
					: resource.getDisplayName() + " (Lv " + resource.getRequiredLevel() + ")";
				setText(label);
				setIcon(getResourceIcon(resource));
				setFont(FontManager.getRunescapeSmallFont());

				if (!isSelected && accountSnapshot.isLoggedIn())
				{
					boolean worldOk = !resource.isMembersOnly() || accountSnapshot.isMembersWorld();
					int playerLevel = resource.getSkill() == GatheringSkill.STATIONS
						? 99
						: accountSnapshot.getSkillLevel(resource.getSkill().getApiSkill());
					if (playerLevel < resource.getRequiredLevel() || !worldOk)
					{
						setForeground(Color.GRAY);
					}
					else
					{
						setForeground(Color.WHITE);
					}
				}
			}
			return this;
		}
	}
}

