import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

public class SpotCatalogTest
{
	@Test
	public void everyResourceHasAtLeastOneSpotAndHighlightMatcher()
	{
		for (ResourceType resource : ResourceType.values())
		{
			List<GatheringSpot> spots = SpotCatalog.getSpotsForResource(resource);
			assertFalse("Resource missing catalog spots: " + resource, spots.isEmpty());
			assertTrue("Resource missing object/NPC ID or action matcher: " + resource, resource.hasHighlightMatcher());
			assertTrue("Invalid level requirement on " + resource, resource.getRequiredLevel() >= 1 && resource.getRequiredLevel() <= 99);
			assertTrue("Invalid icon item ID on " + resource, resource.getIconItemId() > 0);
			assertTrue("Wiki URL must target OSRS Wiki: " + resource, resource.getWikiUrl().startsWith("https://oldschool.runescape.wiki/w/"));
		}
	}

	@Test
	public void everySkillTabHasResourcesAndSpots()
	{
		assertEquals("Expected 8 skill/category tabs", 8, GatheringSkill.values().length);
		for (GatheringSkill skill : GatheringSkill.values())
		{
			assertTrue("Skill missing resources: " + skill, ResourceType.forSkill(skill).length > 0);
			assertFalse("Skill missing spots: " + skill, SpotCatalog.getSpotsForSkill(skill).isEmpty());
		}
		assertFalse("Expected tracked quests across catalog", SpotCatalog.getTrackedQuests().isEmpty());
	}

	@Test
	public void allCatalogSpotsHaveValidCoordinatesAndBankMetadata()
	{
		List<GatheringSpot> allSpots = SpotCatalog.getAllSpots();
		assertTrue("Expected expanded multi-category spot catalog", allSpots.size() >= 130);

		for (GatheringSpot spot : allSpots)
		{
			assertNotNull("Null id", spot.getId());
			assertFalse("Blank id", spot.getId().trim().isEmpty());
			assertNotNull("Null name for " + spot.getId(), spot.getName());
			assertNotNull("Null region for " + spot.getId(), spot.getRegion());
			assertNotNull("Null location for " + spot.getId(), spot.getLocation());
			assertNotNull("Null tip for " + spot.getId(), spot.getTip());
			assertFalse("Blank tip for " + spot.getId(), spot.getTip().trim().isEmpty());
			assertTrue("Node count must be positive for " + spot.getId(), spot.getNodeCount() > 0);
			assertTrue("Highlight radius must be positive for " + spot.getId(), spot.getHighlightRadius() > 0);

			BankInfo bank = spot.getBank();
			assertNotNull("Null bank info for " + spot.getId(), bank);
			if (bank.hasBanking())
			{
				assertNotNull("Bank location missing for " + spot.getId(), bank.getLocation());
				assertTrue("Bank distance must be positive for " + spot.getId(), bank.getDistanceTiles() > 0);
			}
			if (bank.getBankAltSkill() != null)
			{
				assertTrue("Bank alt skill level must be positive for " + spot.getId(), bank.getBankAltSkillLevel() > 0);
				assertFalse("Bank requirement summary must be populated for " + spot.getId(), bank.getBankRequirementSummary().isEmpty());
			}
		}
	}

	@Test
	public void pluginIconsAreValidCompactPngs() throws IOException
	{
		BufferedImage sidebarIcon = ImageUtil.loadImageResource(SpotFinderPlugin.class, "/com/spotfinder/icon.png");
		assertNotNull("Sidebar icon missing", sidebarIcon);
		assertEquals(16, sidebarIcon.getWidth());
		assertEquals(16, sidebarIcon.getHeight());

		BufferedImage mapPin = ImageUtil.loadImageResource(SpotFinderPlugin.class, "/com/spotfinder/map_pin.png");
		assertNotNull("Map pin missing", mapPin);
		assertEquals(24, mapPin.getWidth());
		assertEquals(24, mapPin.getHeight());

		BufferedImage bankPin = ImageUtil.loadImageResource(SpotFinderPlugin.class, "/com/spotfinder/bank_pin.png");
		assertNotNull("Bank pin missing", bankPin);
		assertEquals(24, bankPin.getWidth());
		assertEquals(24, bankPin.getHeight());

		File hubIconFile = new File("icon.png");
		assertTrue("Plugin Hub icon.png missing at repository root", hubIconFile.isFile());
