	@Test
	public void evaluatesSkillQuestDiaryAndBankRequirementsAccurately()
	{
		Map<Skill, Integer> levels = new EnumMap<>(Skill.class);
		levels.put(Skill.WOODCUTTING, 45);
		levels.put(Skill.MINING, 50);
		levels.put(Skill.CRAFTING, 40);

		AccountSnapshot midP2p = AccountSnapshot.builder()
			.loggedIn(true)
			.membersWorld(true)
			.playerLocation(new WorldPoint(3095, 3245, 0))
			.skillLevels(levels)
			.completedQuests(EnumSet.of(Quest.SHILO_VILLAGE))
			.completedDiaries(Collections.emptySet())
			.build();

		GatheringSpot draynorOaks = SpotCatalog.findById("wc-oak-draynor").orElseThrow();
		EvaluatedSpot evalDraynor = SpotRanker.evaluate(draynorOaks, midP2p);
		assertTrue("Lv 45 WC should unlock Draynor oaks", evalDraynor.isUnlocked());
		assertTrue(evalDraynor.getMissingRequirements().isEmpty());
		assertTrue("Player near Draynor should have short distance", evalDraynor.getDistanceFromPlayer() < 15);

		GatheringSpot wcGuildOaks = SpotCatalog.findById("wc-oak-wc-guild").orElseThrow();
		EvaluatedSpot evalGuild = SpotRanker.evaluate(wcGuildOaks, midP2p);
		assertEquals(UnlockStatus.LOCKED, evalGuild.getUnlockStatus());
		assertTrue(evalGuild.getMissingRequirements().stream().anyMatch(s -> s.contains("60 Woodcutting")));

		GatheringSpot shiloSurfaceGems = SpotCatalog.findById("mine-gem-shilo-surface").orElseThrow();
		assertTrue("Shilo Village quest + 50 Mining unlocks surface gem rocks",
			SpotRanker.evaluate(shiloSurfaceGems, midP2p).isUnlocked());

		GatheringSpot shiloUndergroundGems = SpotCatalog.findById("mine-gem-shilo-underground").orElseThrow();
		EvaluatedSpot evalUnderground = SpotRanker.evaluate(shiloUndergroundGems, midP2p);
		assertEquals(UnlockStatus.LOCKED, evalUnderground.getUnlockStatus());
		assertTrue(evalUnderground.getMissingRequirements().contains(DiaryTier.KARAMJA_HARD.getDisplayName()));

		GatheringSpot craftingGuildSilver = SpotCatalog.findById("mine-silver-crafting-guild").orElseThrow();
		EvaluatedSpot evalNoBank = SpotRanker.evaluate(craftingGuildSilver, midP2p);
		assertTrue("Spot itself is unlocked at 40 Crafting + 50 Mining", evalNoBank.isUnlocked());
		assertFalse("Crafting Guild bank chest requires Falador Hard or 99 Crafting", evalNoBank.isBankUnlocked());

		AccountSnapshot withFaladorHard = AccountSnapshot.builder()
			.loggedIn(true)
			.membersWorld(true)
			.skillLevels(levels)
			.completedQuests(Collections.emptySet())
			.completedDiaries(EnumSet.of(DiaryTier.FALADOR_HARD))
			.build();
		assertTrue("Falador Hard Diary unlocks Crafting Guild bank",
			SpotRanker.evaluate(craftingGuildSilver, withFaladorHard).isBankUnlocked());

		Map<Skill, Integer> crafting99 = new EnumMap<>(levels);
		crafting99.put(Skill.CRAFTING, 99);
		AccountSnapshot withCraftingCape = AccountSnapshot.builder()
			.loggedIn(true)
			.membersWorld(true)
			.skillLevels(crafting99)
			.completedQuests(Collections.emptySet())
			.completedDiaries(Collections.emptySet())
			.build();
		assertTrue("99 Crafting unlocks Crafting Guild bank without Falador Hard",
			SpotRanker.evaluate(craftingGuildSilver, withCraftingCape).isBankUnlocked());
	}

	@Test
	public void boostableSpotsRequirePureSkillDeficitWithinFiveLevels()
	{
		GatheringSpot wcGuildOaks = SpotCatalog.findById("wc-oak-wc-guild").orElseThrow();
		GatheringSpot shiloSurfaceGems = SpotCatalog.findById("mine-gem-shilo-surface").orElseThrow();

		AccountSnapshot wc55P2p = AccountSnapshot.builder()
			.loggedIn(true)
			.membersWorld(true)
			.skillLevels(Collections.singletonMap(Skill.WOODCUTTING, 55))
			.completedQuests(Collections.emptySet())
			.completedDiaries(Collections.emptySet())
			.build();
		EvaluatedSpot boostableGuild = SpotRanker.evaluate(wcGuildOaks, wc55P2p);
		assertEquals(UnlockStatus.BOOSTABLE, boostableGuild.getUnlockStatus());
		assertEquals(5, boostableGuild.getMaxBoostNeeded());

		AccountSnapshot wc54P2p = AccountSnapshot.builder()
			.loggedIn(true)
			.membersWorld(true)
			.skillLevels(Collections.singletonMap(Skill.WOODCUTTING, 54))
			.completedQuests(Collections.emptySet())
			.completedDiaries(Collections.emptySet())
			.build();
		EvaluatedSpot tooLowGuild = SpotRanker.evaluate(wcGuildOaks, wc54P2p);
		assertEquals(UnlockStatus.LOCKED, tooLowGuild.getUnlockStatus());
		assertEquals(0, tooLowGuild.getMaxBoostNeeded());

		AccountSnapshot wc55F2p = AccountSnapshot.builder()
			.loggedIn(true)
			.membersWorld(false)
			.skillLevels(Collections.singletonMap(Skill.WOODCUTTING, 55))
			.completedQuests(Collections.emptySet())
			.completedDiaries(Collections.emptySet())
			.build();
		assertEquals("Members blocker prevents boostable status on F2P world",
			UnlockStatus.LOCKED, SpotRanker.evaluate(wcGuildOaks, wc55F2p).getUnlockStatus());

		AccountSnapshot mining37NoQuest = AccountSnapshot.builder()
			.loggedIn(true)
			.membersWorld(true)
			.skillLevels(Collections.singletonMap(Skill.MINING, 37))
			.completedQuests(Collections.emptySet())
			.completedDiaries(Collections.emptySet())
			.build();
		assertEquals("Missing quest prevents boostable status",
			UnlockStatus.LOCKED, SpotRanker.evaluate(shiloSurfaceGems, mining37NoQuest).getUnlockStatus());

		List<EvaluatedSpot> withBoostableIncluded = SpotRanker.rank(
			SpotCatalog.getSpotsForResource(ResourceType.OAK_TREE),
			wc55P2p,
			RankOptions.builder().hideLocked(true).showBoostable(true).includeBoostableInUnlocked(true).build()
		);
		assertTrue(withBoostableIncluded.stream().anyMatch(e -> e.getSpot().getId().equals("wc-oak-wc-guild") && e.isBoostable()));
		assertTrue("Unlocked spots must rank above boostable spots", withBoostableIncluded.get(0).isUnlocked());

		List<EvaluatedSpot> strictUnlocked = SpotRanker.rank(
			SpotCatalog.getSpotsForResource(ResourceType.OAK_TREE),
			wc55P2p,
			RankOptions.builder().hideLocked(true).showBoostable(true).includeBoostableInUnlocked(false).build()
		);
		assertTrue(strictUnlocked.stream().noneMatch(EvaluatedSpot::isBoostable));
	}

	@Test
	public void accountModeDecodingAndIronmanUimWeighting()
	{
		assertEquals(AccountSnapshot.IronmanType.NORMAL, AccountSnapshot.decodeAccountType(0));
		assertEquals(AccountSnapshot.IronmanType.IRONMAN, AccountSnapshot.decodeAccountType(1));
		assertEquals(AccountSnapshot.IronmanType.ULTIMATE_IRONMAN, AccountSnapshot.decodeAccountType(2));
		assertEquals(AccountSnapshot.IronmanType.HARDCORE_IRONMAN, AccountSnapshot.decodeAccountType(3));
		assertEquals(AccountSnapshot.IronmanType.GROUP_IRONMAN, AccountSnapshot.decodeAccountType(4));
		assertEquals(AccountSnapshot.IronmanType.HARDCORE_GROUP_IRONMAN, AccountSnapshot.decodeAccountType(5));
		assertEquals(AccountSnapshot.IronmanType.GROUP_IRONMAN, AccountSnapshot.decodeAccountType(6));

		AccountSnapshot uimAccount = AccountSnapshot.builder()
			.loggedIn(true)
			.membersWorld(true)
			.accountType(AccountSnapshot.IronmanType.ULTIMATE_IRONMAN)
			.skillLevels(Collections.singletonMap(Skill.WOODCUTTING, 90))
			.completedQuests(Collections.emptySet())
			.completedDiaries(Collections.emptySet())
			.build();
		assertEquals(AccountMode.UIM, SpotRanker.resolveAccountMode(AccountMode.AUTO, uimAccount));
		assertEquals(AccountMode.MAIN, SpotRanker.resolveAccountMode(AccountMode.MAIN, uimAccount));

		AccountSnapshot gimAccount = AccountSnapshot.builder()
			.loggedIn(true)
			.membersWorld(true)
			.accountType(AccountSnapshot.IronmanType.GROUP_IRONMAN)
			.skillLevels(Collections.singletonMap(Skill.MINING, 70))
			.completedQuests(Collections.emptySet())
			.completedDiaries(Collections.emptySet())
			.build();
		assertEquals(AccountMode.IRONMAN, SpotRanker.resolveAccountMode(AccountMode.AUTO, gimAccount));

		GatheringSpot sandQuarry = SpotCatalog.findById("mine-sandstone-quarry").orElseThrow();
		EvaluatedSpot mainEval = SpotRanker.evaluate(sandQuarry, gimAccount,
			RankOptions.builder().accountMode(AccountMode.MAIN).build());
		EvaluatedSpot ironEval = SpotRanker.evaluate(sandQuarry, gimAccount,
			RankOptions.builder().accountMode(AccountMode.IRONMAN).build());
		assertTrue("Ironman highlight spot should score higher in Ironman mode", ironEval.getScore() > mainEval.getScore());

		GatheringSpot barbFishing = SpotCatalog.findById("fish-barb-ottos").orElseThrow();
		EvaluatedSpot barbMain = SpotRanker.evaluate(barbFishing, uimAccount,
			RankOptions.builder().accountMode(AccountMode.MAIN).build());
		EvaluatedSpot barbUim = SpotRanker.evaluate(barbFishing, uimAccount,
			RankOptions.builder().accountMode(AccountMode.UIM).build());
		assertTrue("UIM mode weights node density instead of penalizing missing bank", barbUim.getScore() > barbMain.getScore());
	}

