	@Test
	public void sceneNodeScopeRespectsRadiusPlaneGlobalAndActionOnlyResources()
	{
		GatheringSpot draynorOaks = SpotCatalog.findById("wc-oak-draynor").orElseThrow();
		WorldPoint nearNode = new WorldPoint(3105, 3245, 0);
		WorldPoint farNode = new WorldPoint(3250, 3420, 0);
		WorldPoint wrongPlane = new WorldPoint(3105, 3245, 1);

		assertTrue(SceneResourceTracker.isNodeInScope(nearNode, 0, draynorOaks, true));
		assertFalse(SceneResourceTracker.isNodeInScope(farNode, 0, draynorOaks, true));
		assertTrue("Global mode highlights matching nodes anywhere on current plane",
			SceneResourceTracker.isNodeInScope(farNode, 0, draynorOaks, false));
		assertFalse(SceneResourceTracker.isNodeInScope(wrongPlane, 0, draynorOaks, false));

		// Multi-plane Redwood platform walls (plane 1) stay in scope when player climbs to plane 1.
		GatheringSpot redwoods = SpotCatalog.findById("wc-redwood-wc-guild").orElseThrow();
		WorldPoint upperRedwoodWall = new WorldPoint(1570, 3490, 1);
		assertTrue(SceneResourceTracker.isNodeInScope(upperRedwoodWall, 1, redwoods, true));
		assertFalse(SceneResourceTracker.isNodeInScope(upperRedwoodWall, 0, redwoods, true));

		// Action-only resources stay local to the spot radius even in Global mode.
		GatheringSpot draynorRooftop = SpotCatalog.findById("agil-rooftop-draynor").orElseThrow();
		WorldPoint nearClimb = new WorldPoint(3103, 3279, 0);
		WorldPoint farClimb = new WorldPoint(3220, 3414, 0);
		assertTrue(SceneResourceTracker.isNodeInScope(nearClimb, 0, draynorRooftop, false));
		assertFalse("Action-only rooftop start must not highlight ladders across the map in Global mode",
			SceneResourceTracker.isNodeInScope(farClimb, 0, draynorRooftop, false));
	}
}
